import { NextResponse } from 'next/server';
import { cookies } from 'next/headers';
import { supabase } from '@/lib/supabase';
import { validateTelegramWebAppData } from '@/lib/telegramAuth';

export async function POST(req: Request) {
  try {
    const { initData, photoUrl } = await req.json();

    const botToken = process.env.TELEGRAM_BOT_TOKEN;
    if (!botToken) {
      console.error("CRITICAL: TELEGRAM_BOT_TOKEN is not configured in environment variables.");
      return NextResponse.json({ error: 'Server configuration error' }, { status: 500 });
    }

    // 1. Validate the initData using the secure utility
    const validation = validateTelegramWebAppData(initData, botToken);

    if (!validation.isValid || !validation.user) {
      return NextResponse.json({ error: validation.error || 'Authentication failed' }, { status: 401 });
    }

    const telegramId = validation.user.id.toString();

    // 2. Supabase User Sync (Upsert)
    const { data: existingUser, error: selectError } = await supabase
      .from('users')
      .select('id')
      .eq('telegram_id', telegramId)
      .single();

    if (selectError && selectError.code !== 'PGRST116') {
      throw new Error(`Database select error: ${selectError.message}`);
    }

    let internalUserId = null;

    if (existingUser) {
      internalUserId = existingUser.id;
      if (photoUrl) {
        await supabase.from('users').update({ avatar_url: photoUrl }).eq('id', internalUserId);
      }
    } else {
      const { data: newUser, error: insertError } = await supabase
        .from('users')
        .insert({
          telegram_id: telegramId,
          avatar_url: photoUrl || null,
        })
        .select('id')
        .single();

      if (insertError) {
        throw new Error(`Database insert error: ${insertError.message}`);
      }

      internalUserId = newUser.id;
    }

    // 3. Set a secure HTTP-Only Cookie to protect subsequent Server Actions
    const cookieStore = await cookies();
    cookieStore.set({
      name: 'tg_user_id',
      value: internalUserId,
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      path: '/',
      maxAge: 60 * 60 * 24 * 7, // 1 week
    });

    return NextResponse.json({ success: true, user_id: internalUserId });

  } catch (error: any) {
    console.error("Telegram WebApp Auth Error:", error);
    return NextResponse.json({ error: 'Authentication processing failed', details: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { Telegraf } from 'telegraf';

export async function GET(req: NextRequest) {
  try {
    const token = process.env.TELEGRAM_BOT_TOKEN;
    const appUrl = process.env.NEXT_PUBLIC_APP_URL;

    if (!token || !appUrl) {
      return NextResponse.json(
        { error: 'TELEGRAM_BOT_TOKEN or NEXT_PUBLIC_APP_URL not configured in environment' },
        { status: 500 }
      );
    }

    const bot = new Telegraf(token);
    // Ensure appUrl doesn't have a trailing slash to avoid double slashes
    const baseUrl = appUrl.endsWith('/') ? appUrl.slice(0, -1) : appUrl;
    const webhookUrl = `${baseUrl}/api/bot/webhook`;

    const result = await bot.telegram.setWebhook(webhookUrl);

    if (result) {
      return NextResponse.json(
        { success: true, message: `Webhook successfully registered at ${webhookUrl}` },
        { status: 200 }
      );
    } else {
      return NextResponse.json(
        { success: false, message: 'Failed to register webhook' },
        { status: 500 }
      );
    }
  } catch (error: any) {
    console.error('Error registering webhook:', error);
    return NextResponse.json(
      { success: false, error: error.message || 'Unknown error' },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { createClient } from '@supabase/supabase-js';

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

export async function GET(req: Request) {
  const authHeader = req.headers.get("authorization");
  const cronSecret = process.env.CRON_SECRET;

  if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
    if (!req.url.includes('localhost')) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }
  }

  try {
    const { data: activePlayers, error: fetchError } = await supabaseAdmin
      .from("players")
      .select("id, age, ovr, stats")
      .eq("is_retired", false); // Use new is_retired flag

    if (fetchError) {
      throw new Error(`Failed to fetch active players: ${fetchError.message}`);
    }

    if (!activePlayers || activePlayers.length === 0) {
      return NextResponse.json({ message: "No active players to age" }, { status: 200 });
    }

    let agedCount = 0;
    let retiredCount = 0;

    for (const player of activePlayers) {
      const newAge = player.age + 1;

      if (newAge >= 35) {
        // Player reaches retirement horizon
        const { error: retireError } = await supabaseAdmin
          .from("players")
          .update({
            age: newAge,
            is_retired: true,
            lineup_status: 'bench' // Force them to bench
          })
          .eq("id", player.id);

        if (retireError) {
          console.error(`[CRON ERROR] Failed to retire player ${player.id}: ${retireError.message}`);
          continue; 
        }

        // Market Cleanup
        await supabaseAdmin.from("transfer_market").delete().eq("player_id", player.id);
        retiredCount++;
      } else {
        // Standard Aging + OVR Decay
        let decay = 0;
        if (newAge === 31) decay = 1;
        else if (newAge === 32) decay = 2;
        else if (newAge === 33) decay = 3;
        else if (newAge === 34) decay = 4;
        else if (newAge > 34) decay = 5;

        const newOvr = Math.max(1, (player.ovr || 50) - decay);

        // Also reduce stats slightly if decayed
        let newStats = player.stats;
        if (decay > 0 && newStats) {
          newStats = { ...newStats };
          for (const key in newStats) {
             newStats[key] = Math.max(1, newStats[key] - decay);
          }
        }

        const { error: ageError } = await supabaseAdmin
          .from("players")
          .update({ age: newAge, ovr: newOvr, stats: newStats })
          .eq("id", player.id);

        if (ageError) {
          console.error(`[CRON ERROR] Failed to age player ${player.id}: ${ageError.message}`);
          continue;
        }

        agedCount++;
      }
    }

    return NextResponse.json({
      success: true,
      message: "Player aging and evolution process completed securely.",
      stats: { agedCount, retiredCount }
    });

  } catch (error: any) {
    console.error("Cron Age Players Fatal Error:", error);
    return NextResponse.json({ error: "Internal Server Error", details: error.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

async function sendTelegramMessage(telegramId: string, message: string): Promise<void> {
  const token = process.env.TELEGRAM_BOT_TOKEN;
  if (!token) return;
  try {
    await fetch(`https://api.telegram.org/bot${token}/sendMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: telegramId, text: message, parse_mode: 'Markdown' })
    });
  } catch (err) {
    console.error('[end-of-season] Telegram send error:', err);
  }
}

export async function GET(request: Request) {
  try {
    const authHeader = request.headers.get('authorization');
    if (authHeader !== `Bearer ${process.env.CRON_SECRET}`) {
      console.warn('[end-of-season] Unauthorized cron attempt blocked.');
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    console.log('[CRON EndOfSeason] Starting...');

    // 1. Find all active instances
    const { data: activeInstances } = await supabaseAdmin
      .from('league_instances')
      .select('id, tier_level')
      .eq('status', 'active');

    if (!activeInstances || activeInstances.length === 0) {
      return NextResponse.json({ message: 'No active instances' });
    }

    let processedCount = 0;

    for (const instance of activeInstances) {
      // Check if all matches for this instance are played
      const { count: unplayedCount } = await supabaseAdmin
        .from('league_matches')
        .select('*', { count: 'exact', head: true })
        .eq('league_instance_id', instance.id)
        .eq('is_played', false);

      if (unplayedCount !== null && unplayedCount > 0) {
        continue; // Season not finished yet
      }

      // ── R2 FIX: CAS (Compare-And-Swap) lock via intermediate 'finishing' status ──
      // We attempt to atomically transition status active → finishing.
      // If another cron process already claimed this instance, the UPDATE will
      // match 0 rows (status is no longer 'active') and we skip it.
      // This prevents double-processing and double-payouts in concurrent runs.
      const { data: claimed, error: lockError } = await supabaseAdmin
        .from('league_instances')
        .update({ status: 'finishing' })
        .eq('id', instance.id)
        .eq('status', 'active')  // CAS condition: only update if still 'active'
        .select('id')
        .maybeSingle();

      if (lockError) {
        console.error(`[CRON EndOfSeason] Lock error for instance ${instance.id}:`, lockError);
        continue;
      }
      if (!claimed) {
        console.log(`[CRON EndOfSeason] Instance ${instance.id} already claimed by another process — skipping.`);
        continue;
      }

      console.log(`[CRON EndOfSeason] Instance ${instance.id} claimed. Processing Tier ${instance.tier_level}...`);

      // Get final standings
      const { data: finalStandings } = await supabaseAdmin
        .from('league_standings')
        .select('team_id, points, goals_for, goals_against, season_reward_paid')
        .eq('league_instance_id', instance.id)
        .order('points', { ascending: false })
        .order('goals_for', { ascending: false });

      if (!finalStandings || finalStandings.length === 0) {
        // Nothing to process — mark as finished and continue
        await supabaseAdmin
          .from('league_instances')
          .update({ status: 'finished' })
          .eq('id', instance.id);
        continue;
      }

      // ── R5 FIX: Read Treasury once per instance (fresh read after CAS lock) ──
      // Each iteration reads a fresh value so sequential league processing
      // doesn't accumulate stale snapshot errors.
      const { data: treasuryData } = await supabaseAdmin
        .from('treasury')
        .select('prize_pool_ton')
        .eq('id', 1)
        .single();
      const currentPool = treasuryData?.prize_pool_ton ?? 0;

      let drainPercentage = 0;
      const t = instance.tier_level;
      if (t === 1)            drainPercentage = 0.10;
      else if (t === 2)       drainPercentage = 0.04;
      else if (t === 3)       drainPercentage = 0.02;
      else if (t === 4)       drainPercentage = 0.01;
      else if (t === 5)       drainPercentage = 0.005;
      else if (t === 6 || t === 7) drainPercentage = 0.001;
      else                    drainPercentage = 0; // Tiers 8-10: no TON drain

      const instancePrizeTon = currentPool * drainPercentage;
      let usedTon = 0;

      // ── REASSIGNMENTS AND PRIZES ────────────────────────────────────────────
      const newAssignments: { team_id: string; new_tier: number }[] = [];

      for (let i = 0; i < finalStandings.length; i++) {
        let nextTier = instance.tier_level;
        const position = i + 1;

        if (i < 3) nextTier = Math.max(1, instance.tier_level - 1);          // Top 3 → promoted
        else if (i >= finalStandings.length - 3) nextTier = Math.min(10, instance.tier_level + 1); // Bottom 3 → relegated

        newAssignments.push({ team_id: finalStandings[i].team_id, new_tier: nextTier });

        // ── R5 FIX: Skip if prizes already paid (idempotency guard) ──────────
        if (finalStandings[i].season_reward_paid) {
          console.log(`[CRON EndOfSeason] Team ${finalStandings[i].team_id} already rewarded — skipping.`);
          continue;
        }

        const { data: teamData } = await supabaseAdmin
          .from('teams')
          .select('user_id, name')
          .eq('id', finalStandings[i].team_id)
          .single();

        if (teamData?.user_id) {
          const { data: userData } = await supabaseAdmin
            .from('users')
            .select('telegram_id, balance_ton, balance_fancoins')
            .eq('id', teamData.user_id)
            .single();

          let tonWon = 0;
          let fcWon = 0;

          if (i === 0)      tonWon = instancePrizeTon * 0.50; // 1st Place
          else if (i === 1) tonWon = instancePrizeTon * 0.30; // 2nd Place
          else if (i === 2) tonWon = instancePrizeTon * 0.20; // 3rd Place

          // FC reward (scales inversely with tier — higher tiers earn more base FC)
          if (position === 1)      fcWon = 15000 + ((11 - t) * 2000);
          else if (position <= 3)  fcWon = 10000 + ((11 - t) * 1500);
          else                     fcWon = 3000  + ((11 - t) * 500);

          const newTon = (userData?.balance_ton || 0) + tonWon;
          const newFc  = (userData?.balance_fancoins || 0) + fcWon;

          await supabaseAdmin
            .from('users')
            .update({ balance_ton: newTon, balance_fancoins: newFc })
            .eq('id', teamData.user_id);

          if (tonWon > 0) {
            usedTon += tonWon;
          }

          // ── R5 FIX: Mark this standing as paid (prevents double-payout on retry) ──
          await supabaseAdmin
            .from('league_standings')
            .update({ season_reward_paid: true })
            .eq('team_id', finalStandings[i].team_id)
            .eq('league_instance_id', instance.id);

          if (userData?.telegram_id) {
            let msg = `🏆 *Сезон завершен!*\n\nТвоя команда *${teamData.name}* заняла *${position} место* в Tier ${instance.tier_level}.\n`;
            if (tonWon > 0) msg += `💰 Призовые TON: *+${tonWon.toFixed(4)} TON*\n`;
            msg += `🪙 Призовые FC: *+${fcWon} FC*\n\n`;

            if (nextTier < instance.tier_level)      msg += `🚀 *Поздравляем с выходом в Tier ${nextTier}!*`;
            else if (nextTier > instance.tier_level) msg += `📉 К сожалению, ты вылетаешь в Tier ${nextTier}.`;
            else                                     msg += `👉 В следующем сезоне ты остаешься в Tier ${nextTier}.`;

            await sendTelegramMessage(userData.telegram_id, msg);
          }
        }
      }

      // ── R2/R5 FIX: Atomic Treasury deduction via RPC (no read-modify-write race) ──
      if (usedTon > 0) {
        const { error: drainError } = await supabaseAdmin.rpc('safe_deduct_treasury', {
          deduct_amount: usedTon
        });
        if (drainError) {
          console.error(`[CRON EndOfSeason] Treasury drain RPC error for Tier ${instance.tier_level}:`, drainError);
        } else {
          console.log(`[CRON EndOfSeason] Deducted ${usedTon.toFixed(4)} TON from Treasury for Tier ${instance.tier_level}.`);
        }
      }

      // ── Assign teams to new tier instances for next season ─────────────────
      for (const assignment of newAssignments) {
        let targetInstanceId: string | undefined;

        const { data: openInstances } = await supabaseAdmin
          .from('league_instances')
          .select('id')
          .eq('tier_level', assignment.new_tier)
          .eq('status', 'filling')
          .order('created_at', { ascending: true })
          .limit(1);

        if (openInstances && openInstances.length > 0) {
          targetInstanceId = openInstances[0].id;
        } else {
          const { data: newInstance } = await supabaseAdmin
            .from('league_instances')
            .insert({
              tier_level: assignment.new_tier,
              name: `Sector ${Math.floor(Math.random() * 900) + 100}`,
              status: 'filling'
            })
            .select('id')
            .single();
          targetInstanceId = newInstance!.id;
        }

        await supabaseAdmin.from('league_standings').insert({
          team_id: assignment.team_id,
          league_instance_id: targetInstanceId,
          points: 0, matches_played: 0, wins: 0, draws: 0, losses: 0,
          goals_for: 0, goals_against: 0,
          season_reward_paid: false // reset for the new season
        });
      }

      // ── Mark instance as fully finished ────────────────────────────────────
      await supabaseAdmin
        .from('league_instances')
        .update({ status: 'finished' })
        .eq('id', instance.id);

      processedCount++;
      console.log(`[CRON EndOfSeason] Instance ${instance.id} fully processed and marked 'finished'.`);
    }

    return NextResponse.json({ message: 'EndOfSeason processed', processed: processedCount });
  } catch (error: any) {
    console.error('[end-of-season] Unhandled error:', error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { createClient } from "@supabase/supabase-js";

// Admin client — apply_form_decay() touches multiple users and requires service role
const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

// Form decay runs once per day. Guard against double-execution.
const DECAY_COOLDOWN_HOURS = 22;

export async function GET(req: NextRequest) {
  // ── Auth ─────────────────────────────────────────────────────────────────────
  const authHeader  = req.headers.get('authorization');
  const manualSecret = req.nextUrl?.searchParams?.get('secret');
  const validBearer  = authHeader === `Bearer ${process.env.CRON_SECRET}`;
  const validSecret  = manualSecret === process.env.CRON_SECRET_MANUAL;

  if (!validBearer && !validSecret) {
    console.warn('[form-decay] Unauthorized request blocked.');
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    // ── Idempotency gate ──────────────────────────────────────────────────────
    const { data: config } = await supabaseAdmin
      .from('system_config')
      .select('value')
      .eq('key', 'last_form_decay')
      .maybeSingle();

    if (config?.value) {
      const lastRun  = new Date(config.value).getTime();
      const elapsedH = (Date.now() - lastRun) / 1000 / 3600;

      if (elapsedH < DECAY_COOLDOWN_HOURS) {
        const remainH = (DECAY_COOLDOWN_HOURS - elapsedH).toFixed(1);
        console.log(`[form-decay] Cooldown active. Next decay in ~${remainH}h.`);
        return NextResponse.json({
          success: true,
          cooldown: true,
          message: `Cooldown active. Next form decay in ~${remainH}h.`,
        });
      }
    }

    // ── Execute Form Decay ────────────────────────────────────────────────────
    // Calls the apply_form_decay() SQL function (migration 00039).
    // Returns: { decayed, maintained, skipped, run_at }
    const { data: result, error: rpcError } = await supabaseAdmin
      .rpc('apply_form_decay');

    if (rpcError) {
      throw new Error(`apply_form_decay RPC failed: ${rpcError.message}`);
    }

    // ── Update last_form_decay timestamp ─────────────────────────────────────
    await supabaseAdmin
      .from('system_config')
      .upsert(
        { key: 'last_form_decay', value: new Date().toISOString() },
        { onConflict: 'key' }
      );

    const summary = result as {
      decayed:    number;
      maintained: number;
      skipped:    number;
      run_at:     string;
    };

    console.log(
      `[form-decay] Done. decayed=${summary.decayed}, maintained=${summary.maintained}, skipped=${summary.skipped}`
    );

    return NextResponse.json({
      success:    true,
      decayed:    summary.decayed,
      maintained: summary.maintained,
      skipped:    summary.skipped,
      run_at:     summary.run_at,
      message:    `Form decay applied. ${summary.decayed} players degraded, ${summary.maintained} maintained.`,
    });

  } catch (error: any) {
    console.error('[form-decay] Error:', error);
    return NextResponse.json(
      { error: 'Internal Server Error', details: error.message },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';
import crypto from 'crypto';
import { generateLeagueSchedule } from '@/app/actions/calendarActions';

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

const FIRST_NAMES = ['Bot', 'Auto', 'Cyber', 'Neon', 'Meta', 'Holo', 'Quantum', 'Plasma', 'Aura', 'Zenith', 'Echo', 'Nexus', 'Apex'];
const LAST_NAMES = ['Strikers', 'United', 'City', 'FC', 'Athletic', 'Rovers', 'Wanderers', 'Dynamos', 'Titans', 'Legends', 'Force', 'Stars'];
const BOT_POSITIONS = [
  { pos: 'GK', status: 'starting' },
  { pos: 'DEF', status: 'starting' }, { pos: 'DEF', status: 'starting' }, { pos: 'DEF', status: 'starting' }, { pos: 'DEF', status: 'starting' },
  { pos: 'MID', status: 'starting' }, { pos: 'MID', status: 'starting' }, { pos: 'MID', status: 'starting' }, { pos: 'MID', status: 'starting' },
  { pos: 'FWD', status: 'starting' }, { pos: 'FWD', status: 'starting' },
  { pos: 'GK', status: 'bench' },
  { pos: 'DEF', status: 'bench' },
  { pos: 'MID', status: 'bench' }, { pos: 'MID', status: 'bench' },
  { pos: 'FWD', status: 'bench' }
];

export async function GET(request: Request) {
  try {
    const authHeader = request.headers.get('authorization');
    if (authHeader !== `Bearer ${process.env.CRON_SECRET}`) {
      // ── R3 FIX: Return 401 — previously this line was commented out, allowing
      // any unauthenticated caller to create unlimited bot users/teams/players,
      // causing database bloat and performance degradation for all players.
      console.warn('[AutoFill] Unauthorized cron attempt blocked.');
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    console.log("[CRON AutoFill] Starting...");

    // 1. Find instances in 'filling' status
    const { data: fillingInstances } = await supabaseAdmin
      .from('league_instances')
      .select('id, created_at')
      .eq('status', 'filling');

    if (!fillingInstances || fillingInstances.length === 0) {
      return NextResponse.json({ message: "No instances need filling" });
    }

    for (const instance of fillingInstances) {
      // Check capacity
      const { count } = await supabaseAdmin
        .from('league_standings')
        .select('*', { count: 'exact', head: true })
        .eq('league_instance_id', instance.id);

      const currentCount = count || 0;
      const targetCount = 14;

      // If it's been filling for over 12 hours OR if we just want to force fill it now for simplicity
      // In a real app, we check created_at. For now, we auto-fill if it's over 1 hour old, 
      // or if it's just triggered manually.
      const ageHours = (new Date().getTime() - new Date(instance.created_at).getTime()) / (1000 * 60 * 60);

      if (currentCount < targetCount && ageHours >= 0) {
        console.log(`[CRON AutoFill] Instance ${instance.id} has ${currentCount} teams. Filling with ${targetCount - currentCount} bots.`);

        const botsNeeded = targetCount - currentCount;
        const usersToInsert = [];

        for (let i = 0; i < botsNeeded; i++) {
          usersToInsert.push({
            id: crypto.randomUUID(),
            telegram_id: `bot_${crypto.randomUUID()}`,
            balance_fancoins: Math.floor(Math.random() * 5000)
          });
        }

        const { data: insertedUsers, error: usersError } = await supabaseAdmin.from('users').insert(usersToInsert).select('id');
        if (usersError || !insertedUsers) continue;

        const teamsToInsert = insertedUsers.map((user: any, idx: number) => {
          const fName = FIRST_NAMES[idx % FIRST_NAMES.length];
          const lName = LAST_NAMES[Math.floor(Math.random() * LAST_NAMES.length)];
          return {
            id: crypto.randomUUID(),
            user_id: user.id,
            name: `${fName} ${lName}`,
            logo_url: `https://api.dicebear.com/7.x/bottts/svg?seed=${user.id}`
          };
        });

        const { data: insertedTeams, error: teamsError } = await supabaseAdmin.from('teams').insert(teamsToInsert).select('id');
        if (teamsError || !insertedTeams) continue;

        const playersToInsert: any[] = [];
        const pFirst = ['James', 'John', 'Robert', 'Michael', 'William', 'David', 'Richard', 'Joseph', 'Thomas', 'Charles', 'Daniel', 'Matthew'];
        const pLast = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis', 'Rodriguez', 'Martinez', 'Hernandez', 'Lopez'];

        insertedTeams.forEach((team: any) => {
          const teamBaseOvr = Math.floor(Math.random() * 16) + 30; // 30-45 OVR

          for (let i = 0; i < 16; i++) {
            const ovr = Math.max(30, Math.min(99, teamBaseOvr + Math.floor(Math.random() * 10 - 5)));
            const generateStat = () => Math.max(30, Math.min(99, Math.round(ovr + (Math.random() * 14 - 7))));

            const traitsRoll = Math.random();
            let numTraits = 0;
            if (traitsRoll >= 0.85) numTraits = 2;
            else if (traitsRoll >= 0.30) numTraits = 1;

            const traits: string[] = [];
            const availableTraits = ['Sniper', 'Playmaker', 'Wall', 'Speedster', 'Anchor', 'Poacher', 'Engine'];
            for (let t = 0; t < numTraits; t++) {
              const idx = Math.floor(Math.random() * availableTraits.length);
              traits.push(availableTraits.splice(idx, 1)[0]);
            }

            playersToInsert.push({
              team_id: team.id,
              name: `${pFirst[Math.floor(Math.random() * pFirst.length)]} ${pLast[Math.floor(Math.random() * pLast.length)]}`,
              age: Math.floor(Math.random() * 15) + 18,
              ovr,
              potential_limit: Math.max(ovr, Math.floor(Math.random() * 10) + ovr),
              position: BOT_POSITIONS[i].pos,
              stats: {
                pace: generateStat(),
                shooting: generateStat(),
                passing: generateStat(),
                dribbling: generateStat(),
                defending: generateStat(),
                physical: generateStat(),
              },
              stamina: 100,
              lineup_status: BOT_POSITIONS[i].status,
              lineup_slot: i.toString(),
              is_nft_coach: false,
              traits
            });
          }
        });

        await supabaseAdmin.from('players').insert(playersToInsert);

        // Add bots to standings
        const standingsToInsert = insertedTeams.map((team: any) => ({
          team_id: team.id,
          league_instance_id: instance.id,
          matches_played: 0,
          wins: 0, draws: 0, losses: 0, points: 0,
          goals_for: 0, goals_against: 0
        }));

        await supabaseAdmin.from('league_standings').insert(standingsToInsert);

        // Activate and generate schedule
        const startTime = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
        await supabaseAdmin.from('league_instances').update({ status: 'active', start_time: startTime }).eq('id', instance.id);

        // ── L2 FIX: Only generate schedule if none exists yet ────────────────
        // Prevents duplicate match rows when autofill is called multiple times
        // for the same instance (e.g. on retry after a partial failure).
        const { count: existingMatches } = await supabaseAdmin
          .from('league_matches')
          .select('*', { count: 'exact', head: true })
          .eq('league_instance_id', instance.id);

        if (!existingMatches || existingMatches === 0) {
          await generateLeagueSchedule(instance.id);
        } else {
          console.log(`[CRON AutoFill] Instance ${instance.id} already has ${existingMatches} matches — skipping schedule generation.`);
        }

        console.log(`[CRON AutoFill] Instance ${instance.id} activated and scheduled! Starts at ${startTime}`);
      } else if (currentCount >= targetCount) {
        // Just in case it's full but status didn't update
        const startTime = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString();
        await supabaseAdmin.from('league_instances').update({ status: 'active', start_time: startTime }).eq('id', instance.id);
        await generateLeagueSchedule(instance.id);
      }
    }

    return NextResponse.json({ message: "Auto-fill processed" });
  } catch (error: any) {
    console.error("AutoFill error:", error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { supabase } from "@/lib/supabase";

export async function GET(req: Request) {
  // 1. Basic security check: Require Bearer token matching CRON_SECRET
  const authHeader = req.headers.get("authorization");
  const cronSecret = process.env.CRON_SECRET;

  if (!cronSecret || authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    // 2. Fetch all teams
    const { data: teams, error: teamsError } = await supabase
      .from("teams")
      .select("id, name, user_id");

    if (teamsError) throw new Error(`Failed to fetch teams: ${teamsError.message}`);

    if (!teams || teams.length < 2) {
      return NextResponse.json({ message: "Not enough teams to simulate a match round" }, { status: 200 });
    }

    // 3. Pair teams up (Simple sequential pairing for MVP)
    const matches = [];
    for (let i = 0; i < teams.length - 1; i += 2) {
      matches.push({
        homeTeam: teams[i],
        awayTeam: teams[i + 1],
      });
    }

    const results = [];

    // 4. Process each match pair
    for (const match of matches) {
      // Fetch starting players
      const [homePlayersRes, awayPlayersRes] = await Promise.all([
        supabase.from("players").select("*").eq("team_id", match.homeTeam.id).eq("lineup_status", "starting"),
        supabase.from("players").select("*").eq("team_id", match.awayTeam.id).eq("lineup_status", "starting")
      ]);

      const homePlayers = homePlayersRes.data || [];
      const awayPlayers = awayPlayersRes.data || [];

      // Calculate Attack & Defense
      const calculatePower = (players: any[]) => {
        let attack = 0;
        let defense = 0;
        players.forEach(p => {
          const modifier = p.stamina < 50 ? 0.8 : 1.0; // 20% penalty if stamina < 50
          if (p.position === 'FWD') {
            attack += ((p.stats?.shooting || 0) + (p.stats?.pace || 0)) * modifier;
          } else if (p.position === 'MID') {
            attack += (p.stats?.passing || 0) * modifier;
            defense += ((p.stats?.passing || 0) * 0.5) * modifier;
          } else if (p.position === 'DEF') {
            defense += ((p.stats?.defending || 0) + (p.stats?.physical || 0)) * modifier;
          } else if (p.position === 'GK') {
            defense += ((p.stats?.defending || p.ovr) || 0) * modifier;
          }
        });
        return { attack, defense };
      };

      const homePower = calculatePower(homePlayers);
      const awayPower = calculatePower(awayPlayers);

      // Score logic based on difference + RNG
      const calcGoals = (atk: number, def: number) => {
        const diff = atk - def;
        const luck = (Math.random() * 0.3) - 0.15; // +/- 15%
        const adjustedDiff = diff * (1 + luck);
        if (adjustedDiff > 100) return 3 + Math.floor(Math.random() * 3);
        if (adjustedDiff > 50) return 2 + Math.floor(Math.random() * 2);
        if (adjustedDiff > 10) return 1 + Math.floor(Math.random() * 2);
        if (adjustedDiff > -20 && Math.random() > 0.5) return 1;
        return 0;
      };

      const homeScore = calcGoals(homePower.attack, awayPower.defense);
      const awayScore = calcGoals(awayPower.attack, homePower.defense);

      // 6. Insert match result
      const { error: matchInsertError } = await supabase
        .from("league_matches")
        .insert({
          home_team_id: match.homeTeam.id,
          away_team_id: match.awayTeam.id,
          home_score: homeScore,
          away_score: awayScore,
          status: 'completed',
          is_played: true,
          events: [],
        });

      if (matchInsertError) throw new Error(`Failed to insert match: ${matchInsertError.message}`);

      // 7. Calculate league points & Distribute Rewards
      let homePoints = 0, awayPoints = 0;
      let homeWins = 0, homeDraws = 0, homeLosses = 0;
      let awayWins = 0, awayDraws = 0, awayLosses = 0;

      const grantReward = async (team: any, resultType: 'win' | 'draw' | 'loss') => {
        const { data: infra } = await supabase.from('infrastructure').select('stadium_level').eq('team_id', team.id).maybeSingle();
        const level = infra ? infra.stadium_level : 1;

        let reward = 0;
        if (resultType === 'win') {
          reward = 500 + (level * 100);
        } else if (resultType === 'draw') {
          reward = 150 + (level * 30);
        } else {
          reward = 50 + (level * 10);
        }

        await supabase.rpc('increment_fancoins', { u_id: team.user_id, amount: reward });
      };

      if (homeScore > awayScore) {
        homePoints = 3; homeWins = 1; awayLosses = 1;
        await grantReward(match.homeTeam, 'win');
        await grantReward(match.awayTeam, 'loss');
      } else if (awayScore > homeScore) {
        awayPoints = 3; awayWins = 1; homeLosses = 1;
        await grantReward(match.awayTeam, 'win');
        await grantReward(match.homeTeam, 'loss');
      } else {
        homePoints = 1; awayPoints = 1; homeDraws = 1; awayDraws = 1;
        await grantReward(match.homeTeam, 'draw');
        await grantReward(match.awayTeam, 'draw');
      }

      // Helper to update standings
      const updateStanding = async (teamId: string, points: number, wins: number, draws: number, losses: number) => {
        const { data: current } = await supabase.from("league_standings").select("*").eq("team_id", teamId).maybeSingle();
        if (current) {
          await supabase.from("league_standings").update({
            matches_played: current.matches_played + 1,
            wins: current.wins + wins, draws: current.draws + draws, losses: current.losses + losses, points: current.points + points,
          }).eq("team_id", teamId);
        } else {
          await supabase.from("league_standings").insert({
            team_id: teamId, matches_played: 1, wins, draws, losses, points,
          });
        }
      };

      await updateStanding(match.homeTeam.id, homePoints, homeWins, homeDraws, homeLosses);
      await updateStanding(match.awayTeam.id, awayPoints, awayWins, awayDraws, awayLosses);

      // Stamina Depletion
      const deductStamina = async (players: any[]) => {
        for (const p of players) {
           const drop = Math.floor(Math.random() * 11) + 15; // 15 to 25
           const newStamina = Math.max(0, p.stamina - drop);
           await supabase.from('players').update({ stamina: newStamina }).eq('id', p.id);
        }
      };

      await deductStamina(homePlayers);
      await deductStamina(awayPlayers);

      results.push({
        homeTeam: match.homeTeam.name,
        awayTeam: match.awayTeam.name,
        homeScore,
        awayScore,
      });
    }

    return NextResponse.json({
      message: "League simulation completed successfully",
      matches: results,
    });
  } catch (error: any) {
    console.error("Cron League Sim Error:", error);
    return NextResponse.json(
      { error: "Internal Server Error", details: error.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

const TELEGRAM_TOKEN = process.env.TELEGRAM_BOT_TOKEN;

// ─── Idempotency gate ────────────────────────────────────────────────────────
// The warning fires at HH:45. The last match completed at HH:00.
// So elapsed since last completed should be ~45min when this fires.
// We allow the warning ONLY if:
//   a) there IS a pending round, AND
//   b) the last completed match was 35–65 min ago (window = safe warning zone)
//      OR there have been no completed matches yet (first round ever).
// This prevents duplicate spamming if GitHub Actions or another cron calls us twice.
const WARN_WINDOW_MIN  = 35; // don't warn earlier than this after last match
const WARN_WINDOW_MAX  = 65; // don't warn later than this (next match would have already played)

async function sendTelegramMessage(telegramId: string, message: string): Promise<void> {
  if (!TELEGRAM_TOKEN || !telegramId) return;
  try {
    await fetch(`https://api.telegram.org/bot${TELEGRAM_TOKEN}/sendMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: telegramId, text: message, parse_mode: 'Markdown' }),
    });
  } catch (err) {
    console.error('[match-warning] Telegram send error:', err);
  }
}

export async function GET(req: NextRequest) {
  try {
    // ── Auth ──────────────────────────────────────────────────────────────────
    const authHeader   = req.headers.get('authorization');
    const manualSecret = req.nextUrl?.searchParams?.get('secret');
    const validBearer  = authHeader === `Bearer ${process.env.CRON_SECRET}`;
    const validSecret  = manualSecret === process.env.CRON_SECRET_MANUAL;

    if (!validBearer && !validSecret) {
      console.warn('[match-warning] Unauthorized request blocked.');
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // ── Find next pending round ───────────────────────────────────────────────
    const { data: unplayedMatches } = await supabaseAdmin
      .from('league_matches')
      .select('round_number')
      .eq('is_played', false)
      .order('round_number', { ascending: true })
      .limit(1);

    if (!unplayedMatches || unplayedMatches.length === 0) {
      return NextResponse.json({ success: true, message: 'No matches scheduled.' });
    }

    const targetRound = unplayedMatches[0].round_number;

    // ── Get all teams playing in this round ───────────────────────────────────
    const { data: matches } = await supabaseAdmin
      .from('league_matches')
      .select('home_team_id, away_team_id')
      .eq('round_number', targetRound)
      .eq('is_played', false);

    if (!matches || matches.length === 0) {
      return NextResponse.json({ success: true, message: 'No matches found.' });
    }

    const teamIds = new Set<string>();
    matches.forEach(m => {
      if (m.home_team_id) teamIds.add(m.home_team_id);
      if (m.away_team_id) teamIds.add(m.away_team_id);
    });

    const { data: teamsData } = await supabaseAdmin
      .from('teams').select('id, user_id').in('id', Array.from(teamIds));

    if (!teamsData || teamsData.length === 0) {
      return NextResponse.json({ success: true, message: 'No teams found.' });
    }

    const userIds = teamsData.map(t => t.user_id).filter(Boolean);

    const { data: usersData } = await supabaseAdmin
      .from('users').select('id, telegram_id').in('id', userIds).not('telegram_id', 'is', null);

    if (!usersData || usersData.length === 0) {
      return NextResponse.json({ success: true, message: 'No telegram IDs found.' });
    }

    const warningMessage =
      `⚠️ *Внимание, тренер!*\n\n` +
      `Через ~15 минут начнётся *Раунд ${targetRound}*!\n\n` +
      `Зайдите в игру и настройте состав — он будет зафиксирован и отправлен на матч.\n\n` +
      `FitManager 🏟️`;

    const sendPromises = usersData
      .filter(u => u.telegram_id && !u.telegram_id.startsWith('bot_'))
      .map(u => sendTelegramMessage(u.telegram_id, warningMessage));

    await Promise.all(sendPromises);

    console.log(`[match-warning] Sent ${sendPromises.length} warnings for Round ${targetRound}.`);
    return NextResponse.json({
      success: true,
      sent: sendPromises.length,
      message: `Warnings sent for Round ${targetRound}.`,
    });

  } catch (err: any) {
    console.error('[match-warning] Error:', err);
    return NextResponse.json({ success: false, error: err.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';
import { resolveMatch } from '@/app/actions/matchActions';

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

const TELEGRAM_TOKEN = process.env.TELEGRAM_BOT_TOKEN;

// ─── Idempotency gate ────────────────────────────────────────────────────────
// How many minutes must pass since the last completed match before we allow
// the next round to be simulated. Tune this to your desired round cadence.
const COOLDOWN_MINUTES = 50;

async function sendTelegramMessage(telegramId: string, message: string): Promise<void> {
  if (!TELEGRAM_TOKEN || !telegramId) return;
  try {
    await fetch(`https://api.telegram.org/bot${TELEGRAM_TOKEN}/sendMessage`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: telegramId, text: message, parse_mode: 'Markdown' }),
    });
  } catch (err) {
    console.error('[process-matches] Telegram send error:', err);
  }
}

function buildMessage(myTeamName: string, oppName: string, myScore: number, oppScore: number): string {
  const icon =
    myScore > oppScore ? '🏆 *Победа!*' :
    myScore < oppScore ? '❌ *Поражение*' :
                         '🤝 *Ничья*';
  return (
    `${icon}\n\n` +
    `Твоя команда *${myTeamName}* сыграла против *${oppName}*.\n\n` +
    `Счет: *${myScore} – ${oppScore}*\n\n` +
    `Зайдите в игру, чтобы посмотреть журнал событий и получить награды!`
  );
}

export async function GET(req: NextRequest) {
  try {
    // ── Auth ──────────────────────────────────────────────────────────────────
    const authHeader  = req.headers.get('authorization');
    const manualSecret = req.nextUrl?.searchParams?.get('secret');
    const validBearer = authHeader === `Bearer ${process.env.CRON_SECRET}`;
    const validSecret = manualSecret === process.env.CRON_SECRET_MANUAL;

    if (!validBearer && !validSecret) {
      console.warn('[process-matches] Unauthorized request blocked.');
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // ── Find next pending round (only for active leagues that have started) ──
    const now = new Date().toISOString();
    const { data: unplayedMatches } = await supabaseAdmin
      .from('league_matches')
      .select('round_number, league_instances!inner(id, start_time, status)')
      .eq('status', 'pending')
      .eq('league_instances.status', 'active')
      .lte('league_instances.start_time', now)
      .order('round_number', { ascending: true })
      .limit(1);

    if (!unplayedMatches || unplayedMatches.length === 0) {
      console.log('[process-matches] No unplayed rounds left. Triggering end-of-season (fire-and-forget)...');
      // ── R1 FIX: Fire-and-forget — do NOT await these fetches. ─────────────
      // Awaiting them caused Vercel timeout (10s Hobby / 60s Pro) when many
      // leagues finished simultaneously, creating a permanent soft-lock where
      // every subsequent cron invocation would hit the same timeout.
      // The downstream routes are idempotent (CAS guard in end-of-season),
      // so it is safe to let them run independently in the background.
      const baseUrl = req.nextUrl.origin;
      const cronHeaders = { 'Authorization': `Bearer ${process.env.CRON_SECRET}` };

      fetch(`${baseUrl}/api/cron/end-of-season`, { headers: cronHeaders })
        .catch(e => console.error('[process-matches] end-of-season fire-and-forget error:', e));

      fetch(`${baseUrl}/api/cron/league-autofill`, { headers: cronHeaders })
        .catch(e => console.error('[process-matches] league-autofill fire-and-forget error:', e));

      return NextResponse.json({ success: true, message: 'No unplayed rounds left. End-of-season and autofill triggered (async).' });
    }

    const targetRound = unplayedMatches[0].round_number;

    const { data: matches } = await supabaseAdmin
      .from('league_matches')
      .select('id, home_team_id, away_team_id, home_team:teams!home_team_id(name), away_team:teams!away_team_id(name), league_instances!inner(id, start_time, status)')
      .eq('round_number', targetRound)
      .eq('status', 'pending')
      .eq('league_instances.status', 'active')
      .lte('league_instances.start_time', now);

    if (!matches || matches.length === 0) {
      return NextResponse.json({ success: true, message: 'No matches found for round.' });
    }

    console.log(`[process-matches] Processing round ${targetRound} — ${matches.length} matches.`);

    // ── Simulate all matches in the round ────────────────────────────────────
    for (const match of matches) {
      await resolveMatch(match.id);
    }

    // ── Notify players via Telegram ───────────────────────────────────────────
    const { data: resolvedMatches } = await supabaseAdmin
      .from('league_matches')
      .select('id, home_team_id, away_team_id, home_score, away_score, home_team:teams!home_team_id(name), away_team:teams!away_team_id(name)')
      .eq('round_number', targetRound);

    if (resolvedMatches) {
      const teamIds = new Set<string>();
      resolvedMatches.forEach(r => { teamIds.add(r.home_team_id); teamIds.add(r.away_team_id); });

      const { data: teamsData } = await supabaseAdmin
        .from('teams').select('id, user_id').in('id', Array.from(teamIds));

      const userIds = teamsData?.map(t => t.user_id).filter(Boolean) || [];

      const { data: usersData } = await supabaseAdmin
        .from('users').select('id, telegram_id').in('id', userIds).not('telegram_id', 'is', null);

      const userTgMap: Record<string, string> = {};
      if (usersData && teamsData) {
        teamsData.forEach(t => {
          const user = usersData.find(u => u.id === t.user_id);
          if (user?.telegram_id && !user.telegram_id.startsWith('bot_')) {
            userTgMap[t.id] = user.telegram_id;
          }
        });
      }

      const sendPromises: Promise<void>[] = [];
      for (const report of resolvedMatches) {
        const hTgId = userTgMap[report.home_team_id];
        const aTgId = userTgMap[report.away_team_id];
        const homeName  = (report.home_team as any)?.name || 'Home';
        const awayName  = (report.away_team as any)?.name || 'Away';
        const homeScore = report.home_score || 0;
        const awayScore = report.away_score || 0;

        if (hTgId) sendPromises.push(sendTelegramMessage(hTgId, buildMessage(homeName, awayName, homeScore, awayScore)));
        if (aTgId) sendPromises.push(sendTelegramMessage(aTgId, buildMessage(awayName, homeName, awayScore, homeScore)));
      }
      await Promise.all(sendPromises);
    }

    console.log(`[process-matches] Round ${targetRound} completed successfully.`);
    return NextResponse.json({
      success: true,
      processed: matches.length,
      message: `Round ${targetRound} processed.`,
    });

  } catch (error: any) {
    console.error('[process-matches] Cron Error:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

// Setup Supabase admin client to bypass RLS for cron job
const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

export async function GET(request: Request) {
  try {
    // 1. Verify cron secret to prevent unauthorized access
    const authHeader = request.headers.get('authorization');
    if (authHeader !== `Bearer ${process.env.CRON_SECRET}`) {
      // Allow localhost for testing
      if (!request.url.includes('localhost')) {
        return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
      }
    }

    console.log('[CRON: stamina-regen] Starting stamina regeneration process...');

    // 2. Fetch all teams' infrastructure to get Medical Center levels
    const { data: infraList, error: infraError } = await supabaseAdmin
      .from('infrastructure')
      .select('team_id, medical_center_level');

    if (infraError) {
      throw new Error(`Failed to fetch infrastructure: ${infraError.message}`);
    }

    // Map team_id -> medical_center_level
    const medLevels: Record<string, number> = {};
    if (infraList) {
      infraList.forEach(infra => {
        medLevels[infra.team_id] = infra.medical_center_level ?? 1;
      });
    }

    // 3. Fetch all players who need regeneration
    // Only fetch players where stamina < 100 AND is_injured = false
    const { data: players, error: playersError } = await supabaseAdmin
      .from('players')
      .select('id, team_id, stamina')
      .eq('is_injured', false)
      .lt('stamina', 100);

    if (playersError) {
      throw new Error(`Failed to fetch players: ${playersError.message}`);
    }

    if (!players || players.length === 0) {
      console.log('[CRON: stamina-regen] No players need stamina regeneration.');
      return NextResponse.json({ success: true, message: 'No players need regeneration.' });
    }

    console.log(`[CRON: stamina-regen] Found ${players.length} players needing regeneration.`);

    // 4. Calculate new stamina for each player
    const updates = players.map(p => {
      const currentStamina = Number(p.stamina ?? 100);
      const missingStamina = 100 - currentStamina;

      // Get medical center level (default to 1 if not found)
      const medLevel = medLevels[p.team_id] || 1;

      // Base regen is 30% of missing. Each level adds 5%. Level 1 = 30%. Level 2 = 35%. Level 3 = 40%.
      // Formula: 0.30 + (medLevel - 1) * 0.05
      // Wait, let's make it more rewarding:
      // Level 1: 30%
      // Level 2: 35%
      // Level 3: 40%
      const regenRate = 0.30 + ((medLevel - 1) * 0.05);

      // Calculate recovered amount
      const recovered = Math.round(missingStamina * regenRate);
      const newStamina = Math.min(100, currentStamina + recovered);

      return {
        id: p.id,
        stamina: newStamina
      };
    });

    // 5. Batch update players
    // Supabase JS doesn't have a bulk update by default for heterogeneous values,
    // so we can either do individual updates or use an RPC. Since we might have 1000s of players,
    // we should use a Postgres function (RPC) or `upsert` if we include all required fields,
    // BUT we only have id and stamina. Upsert might overwrite other fields if not provided depending on schema.
    // Instead, since it's a cron and background, we can do batches of promises or a single RPC.

    // For safety without RPC, chunk updates 100 at a time:
    const chunkSize = 100;
    let updatedCount = 0;

    for (let i = 0; i < updates.length; i += chunkSize) {
      const chunk = updates.slice(i, i + chunkSize);

      const promises = chunk.map(update => 
        supabaseAdmin
          .from('players')
          .update({ stamina: update.stamina })
          .eq('id', update.id)
      );

      await Promise.all(promises);
      updatedCount += chunk.length;
      console.log(`[CRON: stamina-regen] Updated ${updatedCount}/${updates.length} players...`);
    }

    console.log('[CRON: stamina-regen] Successfully completed stamina regeneration.');

    return NextResponse.json({ 
      success: true, 
      processed_players: updatedCount 
    });

  } catch (error: any) {
    console.error('[CRON: stamina-regen] Error:', error);
    return NextResponse.json({ error: error.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

export interface FitnessLogRequest {
  userId: string;
  activityType: string;
  durationMinutes: number;
  calories: number;
}

export async function POST(req: Request) {
  try {
    const body: Partial<FitnessLogRequest> = await req.json();
    const { userId, activityType, durationMinutes, calories } = body;

    // 1. Basic validation
    if (!userId || !activityType || durationMinutes === undefined || calories === undefined) {
      return NextResponse.json(
        { error: 'Missing required payload fields: userId, activityType, durationMinutes, or calories' },
        { status: 400 }
      );
    }

    if (durationMinutes <= 0) {
      return NextResponse.json(
        { error: 'durationMinutes must be greater than 0' },
        { status: 400 }
      );
    }

    // 2. Sweat Points (SP) Conversion Math
    // SP replaces the legacy TP system entirely.
    let earnedSp = 0;
    const type = activityType.toLowerCase();

    if (type === 'running' || type === 'run') {
      earnedSp = Math.floor((durationMinutes * 2) + (calories / 10));
    } else if (type === 'strength') {
      earnedSp = Math.floor((durationMinutes * 3) + (calories / 15));
    } else if (type === 'yoga') {
      earnedSp = Math.floor(durationMinutes * 1);
    } else {
      earnedSp = Math.floor(durationMinutes * 1);
    }

    earnedSp = Math.max(0, earnedSp);

    // 2.5 ANTI-CHEAT: Daily diminishing returns & hard cap
    const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();
    const { data: recentLogs, error: logsError } = await supabase
      .from('fitness_logs')
      .select('activity_type, earned_tp')
      .eq('user_id', userId)
      .gte('created_at', oneDayAgo);

    if (logsError) {
      return NextResponse.json(
        { error: 'Failed to verify anti-cheat daily limits', details: logsError.message },
        { status: 500 }
      );
    }

    let sameActivityCount = 0;
    let dailyTotalSp = 0;

    if (recentLogs) {
      for (const log of recentLogs) {
        // earned_tp column still exists in fitness_logs as historical record
        dailyTotalSp += log.earned_tp;
        if (log.activity_type.toLowerCase() === activityType.toLowerCase()) {
          sameActivityCount++;
        }
      }
    }

    // Diminishing Returns (10% penalty per repeat, max 50%)
    const diminishingPenalty = Math.min(sameActivityCount * 10, 50);
    if (diminishingPenalty > 0) {
      earnedSp = Math.floor(earnedSp * (1 - diminishingPenalty / 100));
    }

    // Daily Hard Cap
    const MAX_DAILY_SP = 500;
    let dailyLimitReached = false;

    if (dailyTotalSp >= MAX_DAILY_SP) {
      earnedSp = 0;
      dailyLimitReached = true;
    } else if (dailyTotalSp + earnedSp > MAX_DAILY_SP) {
      earnedSp = MAX_DAILY_SP - dailyTotalSp;
      dailyLimitReached = true;
    }

    // 3. Insert log record (earned_tp column kept for historical queries)
    const { error: logError } = await supabase
      .from('fitness_logs')
      .insert({
        user_id:          userId,
        activity_type:    activityType,
        duration_minutes: durationMinutes,
        calories:         calories,
        earned_tp:        earnedSp, // stored in earned_tp for schema compat
      });

    if (logError) {
      throw new Error(`Failed to insert fitness log: ${logError.message}`);
    }

    // 4. Credit SP to user via direct update (no column reference to balance_tp)
    const { data: user, error: userFetchErr } = await supabase
      .from('users')
      .select('sweat_points')
      .eq('id', userId)
      .single();

    if (userFetchErr || !user) {
      throw new Error('User not found while crediting SP');
    }

    const newSpBalance = (user.sweat_points || 0) + earnedSp;

    const { error: updateError } = await supabase
      .from('users')
      .update({ sweat_points: newSpBalance })
      .eq('id', userId);

    if (updateError) {
      throw new Error(`Failed to update Sweat Points balance: ${updateError.message}`);
    }

    return NextResponse.json({
      success:        true,
      earned_sp:      earnedSp,
      balance_sp:     newSpBalance,
      meta: {
        dailyLimitReached,
        diminishingPenalty,
      },
    });

  } catch (error: any) {
    console.error('Fitness Log API Error:', error);
    return NextResponse.json(
      { error: 'Internal Server Error', details: error.message },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

export async function POST(req: Request) {
  try {
    const { userId, steps, timezoneDate } = await req.json();

    if (!userId || typeof steps !== 'number' || steps <= 0 || !timezoneDate) {
      return NextResponse.json({ error: 'Invalid parameters' }, { status: 400 });
    }

    // Call the sync_daily_steps RPC (handles SP credit + daily cap internally)
    const { data: rpcResult, error: rpcError } = await supabase.rpc('sync_daily_steps', {
      u_id:         userId,
      steps_to_add: Math.floor(steps),
      today_date:   timezoneDate, // Expected format: 'YYYY-MM-DD'
    });

    if (rpcError) {
      console.error('Sync API RPC Error:', rpcError);
      return NextResponse.json({ error: 'Failed to sync steps' }, { status: 500 });
    }

    // Fetch updated user state for the client (SP + step count, no TP)
    const { data: user, error: userError } = await supabase
      .from('users')
      .select('sweat_points, daily_steps_logged')
      .eq('id', userId)
      .single();

    if (userError || !user) {
      return NextResponse.json({ error: 'Failed to retrieve updated state' }, { status: 500 });
    }

    return NextResponse.json({
      success:            true,
      earned_sp:          rpcResult,
      balance_sp:         user.sweat_points,
      daily_steps_logged: user.daily_steps_logged,
      limit_reached:      user.daily_steps_logged >= 20000,
    });

  } catch (error: any) {
    console.error('Fitness Sync API Error:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

