export async function POST(req: Request) {
  try {
    const body = await req.json();
    const { userId, buildingType } = body; // buildingType: 'stadium' | 'training_camp' | 'medical_center'

    if (!userId || !['stadium', 'training_camp', 'medical_center'].includes(buildingType)) {
      return NextResponse.json({ error: 'Invalid parameters' }, { status: 400 });
    }

    // 1. Get user data for FanCoins balance and team_id
    const [userRes, teamRes] = await Promise.all([
      supabase.from('users').select('balance_fancoins').eq('id', userId).single(),
      supabase.from('teams').select('id').eq('user_id', userId).single()
    ]);

    if (userRes.error || !userRes.data || teamRes.error || !teamRes.data) {
      return NextResponse.json({ error: 'User or Team not found' }, { status: 404 });
    }

    const currentFancoins = userRes.data.balance_fancoins;
    const teamId = teamRes.data.id;

    // 2. Get current infrastructure level
    const { data: infra, error: infraError } = await supabase
      .from('infrastructure')
      .select(`${buildingType}_level`)
      .eq('team_id', teamId)
      .single();

    if (infraError || !infra) {
      return NextResponse.json({ error: 'Infrastructure not found' }, { status: 404 });
    }

    const currentLevel = infra[`${buildingType}_level` as keyof typeof infra] as number;
    const upgradeCost = currentLevel * 1000;

    // 3. Check balance
    if (currentFancoins < upgradeCost) {
      return NextResponse.json({ error: 'Insufficient FanCoins' }, { status: 400 });
    }

    // 4. Perform upgrade (deduct coins and increment level)
    const newBalance = currentFancoins - upgradeCost;
    const newLevel = currentLevel + 1;

    // Use a Promise.all to pseudo-transaction this for MVP
    const [updateUserRes, updateInfraRes] = await Promise.all([
      supabase.from('users').update({ balance_fancoins: newBalance }).eq('id', userId),
      supabase.from('infrastructure').update({ [`${buildingType}_level`]: newLevel }).eq('team_id', teamId).select().single()
    ]);

    if (updateUserRes.error || updateInfraRes.error) {
      console.error("Upgrade error:", updateUserRes.error, updateInfraRes.error);
      return NextResponse.json({ error: 'Failed to process upgrade transaction' }, { status: 500 });
    }

    return NextResponse.json({
      success: true,
      infrastructure: updateInfraRes.data,
      new_balance: newBalance
    });

  } catch (error: any) {
    console.error("Infrastructure POST API Error:", error);
    return NextResponse.json({ error: 'Internal Server Error', details: error.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

export async function GET(req: Request) {
  try {
    const { searchParams } = new URL(req.url);
    const userId = searchParams.get('userId');

    let userTeamId = null;
    let targetLeagueId = null;

    // 1. Find the current user's team ID and their league instance
    if (userId) {
       const { data: teamData } = await supabaseAdmin.from('teams').select('id').eq('user_id', userId).single();
       if (teamData) {
         userTeamId = teamData.id;
         const { data: userStanding } = await supabaseAdmin.from('league_standings')
           .select('league_instance_id')
           .eq('team_id', userTeamId)
           .single();
         if (userStanding) {
           targetLeagueId = userStanding.league_instance_id;
         }
       }
    }

    // If we couldn't find a target league (user has no team or is not in a league yet),
    // we can either return empty or a default league. We'll return empty for safety.
    if (!targetLeagueId) {
       return NextResponse.json({
         success: true,
         standings: [],
         recentMatches: [],
         userTeamId,
         league_instance: null
       });
    }

    // 2. Fetch Standings ONLY for the target league
    const { data: standingsData, error: standingsError } = await supabaseAdmin
      .from('league_standings')
      .select('*, team:teams(name), league_instance:league_instances(tier_level)')
      .eq('league_instance_id', targetLeagueId)
      .order('points', { ascending: false })
      .order('wins', { ascending: false })
      .order('matches_played', { ascending: true });

    if (standingsError) {
      console.error("League Standings Fetch Error:", standingsError);
      return NextResponse.json({ error: 'Failed to fetch standings' }, { status: 500 });
    }

    // Map to include team_name directly to preserve frontend compatibility
    const standings = standingsData?.map(s => ({
      ...s,
      team_name: (s.team as any)?.name || 'Unknown'
    })) || [];

    // 3. Fetch Recent Match History ONLY for the target league
    const { data: matches, error: matchesError } = await supabaseAdmin
      .from('league_matches')
      .select(`
        id, 
        home_score, 
        away_score, 
        created_at,
        home_team:teams!league_matches_home_team_id_fkey (id, name),
        away_team:teams!league_matches_away_team_id_fkey (id, name)
      `)
      .eq('league_instance_id', targetLeagueId)
      .eq('status', 'completed')
      .order('created_at', { ascending: false })
      .limit(20);

    if (matchesError) {
      console.error("Match History Fetch Error:", matchesError);
    }

    return NextResponse.json({
      success: true,
      standings: standings || [],
      recentMatches: matches || [],
      userTeamId,
      league_instance: standingsData?.[0]?.league_instance || null
    });

  } catch (error: any) {
    console.error("League API Error:", error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

