import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

export interface MarketListRequest {
  userId: string;
  playerId: string;
  priceTon: number;
}

const LISTING_FEE_FANCOINS = 100;

export async function POST(req: Request) {
  try {
    const body: Partial<MarketListRequest> = await req.json();
    const { userId, playerId, priceTon } = body;

    // 1. Payload Verification
    if (!userId || !playerId || priceTon === undefined || priceTon <= 0) {
      return NextResponse.json(
        { error: 'Missing or invalid payload fields: userId, playerId, or priceTon' },
        { status: 400 }
      );
    }

    // 2. Verify Player Ownership
    // Extract the team_id for the player
    const { data: playerData, error: playerError } = await supabase
      .from('players')
      .select('id, team_id')
      .eq('id', playerId)
      .single();

    if (playerError || !playerData) {
      return NextResponse.json(
        { error: 'Player not found or database read error' },
        { status: 404 }
      );
    }

    // Verify the team belongs to the requesting user
    const { data: teamData, error: teamError } = await supabase
      .from('teams')
      .select('user_id')
      .eq('id', playerData.team_id)
      .single();

    if (teamError || !teamData || teamData.user_id !== userId) {
      return NextResponse.json(
        { error: 'Forbidden: You do not own the team this player belongs to' },
        { status: 403 }
      );
    }

    // 3. Spam Defense: Check for existing active listing
    const { data: existingListing } = await supabase
      .from('transfer_market')
      .select('id')
      .eq('player_id', playerId)
      .eq('is_active', true)
      .single();

    if (existingListing) {
      return NextResponse.json(
        { error: 'Conflict: This player is already listed actively on the market' },
        { status: 409 }
      );
    }

    // 4. Economic Verification & Burn (Simulated Transaction)
    // Fetch user FanCoin balance
    const { data: user, error: userError } = await supabase
      .from('users')
      .select('balance_fancoins')
      .eq('id', userId)
      .single();

    if (userError || !user) {
      return NextResponse.json(
        { error: 'User not found during economic validation' },
        { status: 404 }
      );
    }

    const currentBalance = Number(user.balance_fancoins) || 0;

    if (currentBalance < LISTING_FEE_FANCOINS) {
      return NextResponse.json(
        { error: `Insufficient FanCoins. Required: ${LISTING_FEE_FANCOINS}, Balance: ${currentBalance}` },
        { status: 400 }
      );
    }

    const newBalance = currentBalance - LISTING_FEE_FANCOINS;

    // Deduct coins preemptively (if market insert fails, we refund via catch block)
    const { error: deductError } = await supabase
      .from('users')
      .update({ balance_fancoins: newBalance })
      .eq('id', userId);

    if (deductError) {
      throw new Error(`Failed to deduct FanCoins: ${deductError.message}`);
    }

    // 5. Insert Market Listing
    const { data: marketListing, error: marketError } = await supabase
      .from('transfer_market')
      .insert({
        player_id: playerId,
        seller_id: userId,
        price_ton: priceTon,
        is_active: true,
      })
      .select('id')
      .single();

    if (marketError) {
      // Manual Rollback: Refund FanCoins
      console.error("Market insert failed, initiating rollback...", marketError);
      await supabase
        .from('users')
        .update({ balance_fancoins: currentBalance })
        .eq('id', userId);

      throw new Error(`Failed to create market listing: ${marketError.message}. FanCoins successfully refunded.`);
    }

    // 6. Return Success
    return NextResponse.json({
      success: true,
      listing_id: marketListing.id,
      new_balance_fancoins: newBalance,
    });

  } catch (error: any) {
    console.error("Market Listing API Error:", error);
    return NextResponse.json(
      { error: 'Internal Server Error', details: error.message },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';

export async function GET() {
  try {
    // 1. Fetch latest 10 matches
    const { data: matches, error: matchError } = await supabase
      .from('league_matches')
      .select('id, home_team_id, away_team_id, home_score, away_score, created_at')
      .eq('status', 'completed')
      .order('created_at', { ascending: false })
      .limit(10);

    if (matchError) {
      throw new Error(`Failed to fetch matches: ${matchError.message}`);
    }

    if (!matches || matches.length === 0) {
      return NextResponse.json({ success: true, matches: [] });
    }

    // 2. Fetch corresponding team names efficiently
    const teamIds = [...new Set(matches.flatMap(m => [m.home_team_id, m.away_team_id]))];
    const { data: teams, error: teamsError } = await supabase
      .from('teams')
      .select('id, name')
      .in('id', teamIds);

    if (teamsError) {
      throw new Error(`Failed to fetch team names for journal mapping: ${teamsError.message}`);
    }

    // Create a dictionary for quick lookup
    const teamMap: Record<string, string> = {};
    if (teams) {
      teams.forEach(t => teamMap[t.id] = t.name);
    }

    // 3. Map into the final enriched payload
    const enrichedMatches = matches.map(m => ({
      id: m.id,
      home_score: m.home_score,
      away_score: m.away_score,
      match_date: (m as any).created_at,
      home_team_name: teamMap[m.home_team_id] || 'Unknown Home',
      away_team_name: teamMap[m.away_team_id] || 'Unknown Away',
    }));

    return NextResponse.json({
      success: true,
      matches: enrichedMatches,
    });
  } catch (error: any) {
    console.error("Match History API Error:", error);
    return NextResponse.json(
      { error: 'Internal Server Error', details: error.message },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);

// GET /api/matches/recent?teamId=<uuid>&limit=<n>
// Returns the last N played matches for a team, enriched with team names.
// Used by the Dashboard horizontal match history carousel.
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const teamId = searchParams.get('teamId');
  const limit  = Math.min(parseInt(searchParams.get('limit') || '10', 10), 30);

  if (!teamId) {
    return NextResponse.json({ error: 'teamId is required' }, { status: 400 });
  }

  try {
    const { data: matches, error } = await supabaseAdmin
      .from('league_matches')
      .select(`
        id,
        round_number,
        home_score,
        away_score,
        is_played,
        home_team:teams!league_matches_home_team_id_fkey(id, name, logo_url),
        away_team:teams!league_matches_away_team_id_fkey(id, name, logo_url)
      `)
      .or(`home_team_id.eq.${teamId},away_team_id.eq.${teamId}`)
      .eq('is_played', true)
      .order('round_number', { ascending: false })
      .limit(limit);

    if (error) {
      console.error('[api/matches/recent] DB error:', error);
      return NextResponse.json({ error: error.message }, { status: 500 });
    }

    return NextResponse.json({ matches: matches || [] });
  } catch (err: any) {
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';
import { createClient } from '@supabase/supabase-js';
import { executeBotSeeding } from '@/app/actions/adminActions';
import { generateLeagueSchedule } from '@/app/actions/calendarActions';

export interface PlayerStats {
  pace: number;
  shooting: number;
  passing: number;
  defending: number;
  physical: number;
}

function getRandomInt(min: number, max: number) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

const AVAILABLE_TRAITS = ['Sniper', 'Playmaker', 'Wall', 'Speedster', 'Anchor', 'Poacher', 'Engine'];

import { getRandomName } from '@/app/utils/nameGenerator';

function generatePlayer(teamId: string, position: string, lineup_status: string = 'starting', lineup_slot: string | null = null) {
  const stats: PlayerStats = {
    pace: getRandomInt(45, 65),
    shooting: getRandomInt(45, 65),
    passing: getRandomInt(45, 65),
    defending: getRandomInt(45, 65),
    physical: getRandomInt(45, 65),
  };

  const ovr = Math.floor((stats.pace + stats.shooting + stats.passing + stats.defending + stats.physical) / 5);
  const age = getRandomInt(18, 25);

  const name = getRandomName();

  const traitsRoll = Math.random();
  let numTraits = 0;
  if (traitsRoll >= 0.85) {
    numTraits = 2;
  } else if (traitsRoll >= 0.30) {
    numTraits = 1;
  }

  const traits: string[] = [];
  const available = [...AVAILABLE_TRAITS];
  for (let i = 0; i < numTraits; i++) {
    const idx = getRandomInt(0, available.length - 1);
    traits.push(available.splice(idx, 1)[0]);
  }

  return {
    team_id: teamId,
    name,
    age,
    ovr,
    potential_limit: getRandomInt(ovr + 5, 90),
    is_nft_coach: false,
    position,
    stats,
    stamina: 100,
    lineup_status,
    lineup_slot,
    traits
  };
}

export async function POST(req: Request) {
  try {
    const { userId, teamName } = await req.json();

    if (!userId || !teamName) {
      return NextResponse.json({ error: 'Missing userId or teamName' }, { status: 400 });
    }

    const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
    const supabaseServiceKey = process.env.SUPABASE_SERVICE_ROLE_KEY!;
    const supabaseAdmin = createClient(supabaseUrl, supabaseServiceKey);

    // === WIPE PHASE ===
    // 1. Delete user's current team (cascades players, chemistry, standings, user matches)
    await supabaseAdmin.from('teams').delete().eq('user_id', userId);

    // 2. Delete all bot users (cascades their teams, players, standings, matches)
    await supabaseAdmin.from('users').delete().like('telegram_id', 'bot_%');

    // 3. Force clean calendar (in case cascade left anything)
    await supabaseAdmin.from('league_matches').delete().neq('id', '00000000-0000-0000-0000-000000000000');

    // === CREATE PHASE ===
    // 4. Create new team for user
    const { data: newTeam, error: teamError } = await supabaseAdmin
      .from('teams')
      .insert({ user_id: userId, name: teamName })
      .select()
      .single();

    if (teamError || !newTeam) {
      return NextResponse.json({ error: 'Failed to create team' }, { status: 500 });
    }

    // 5. Procedural Squad Generation (16 Players)
    const positions = [
      { pos: 'GK', status: 'starting' },
      { pos: 'DEF', status: 'starting' }, { pos: 'DEF', status: 'starting' }, { pos: 'DEF', status: 'starting' }, { pos: 'DEF', status: 'starting' },
      { pos: 'MID', status: 'starting' }, { pos: 'MID', status: 'starting' }, { pos: 'MID', status: 'starting' }, { pos: 'MID', status: 'starting' },
      { pos: 'FWD', status: 'starting' }, { pos: 'FWD', status: 'starting' },
      { pos: 'GK', status: 'bench' },
      { pos: 'DEF', status: 'bench' },
      { pos: 'MID', status: 'bench' }, { pos: 'MID', status: 'bench' },
      { pos: 'FWD', status: 'bench' }
    ];

    const playersToInsert = positions.map((p, index) => generatePlayer(newTeam.id, p.pos, p.status, index.toString()));

    // 6. Batch Insert Players
    const { data: players, error: playersError } = await supabaseAdmin
      .from('players')
      .insert(playersToInsert)
      .select();

    if (playersError) {
      // Rollback team creation if players fail
      await supabaseAdmin.from('teams').delete().eq('id', newTeam.id);
      return NextResponse.json({ error: 'Failed to generate players, team creation rolled back', details: playersError.message }, { status: 500 });
    }

    // 7. Initialize user's league standings
    await supabaseAdmin.from('league_standings').insert({ team_id: newTeam.id });

    // 8. Initialize user's infrastructure
    await supabaseAdmin.from('infrastructure').insert({ team_id: newTeam.id });

    // === COLD START PHASE ===
    // 9. Seed the league with 13 fresh bot teams
    const seedRes = await executeBotSeeding(supabaseAdmin);
    if (!seedRes.success) {
      console.warn("Failed to seed bot league:", seedRes.error);
      // We don't rollback user team, but schedule won't generate properly
    }

    // 10. Generate full calendar grid for the 14 teams
    const calRes = await generateLeagueSchedule();
    if (!calRes.success) {
      console.warn("Failed to generate schedule:", calRes.error);
    }

    return NextResponse.json({
      success: true,
      team: newTeam,
      players
    });

  } catch (error: any) {
    console.error("Team Creation API Error:", error);
    return NextResponse.json(
      { error: 'Internal Server Error', details: error.message },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

const supabaseAdmin = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.SUPABASE_SERVICE_ROLE_KEY!
);
import { cookies } from 'next/headers';

export async function GET(req: Request) {
  try {
    const cookieStore = await cookies();
    const userId = cookieStore.get('tg_user_id')?.value;

    if (!userId) {
      return NextResponse.json({ error: 'Missing or invalid user session' }, { status: 401 });
    }

    // 1. Fetch the team metadata for the user securely
    const { data: team, error: teamError } = await supabaseAdmin
      .from('teams')
      .select('id, name, logo_url, is_ready_for_match, formation')
      .eq('user_id', userId)
      .single();

    if (teamError || !team) {
      return NextResponse.json({ success: true, team: null, players: [] }, { status: 200 });
    }

    // 1.5 Fetch instance info
    let instanceStatus = 'active';
    let instanceCreatedAt = null;
    let teamCount = 1;

    const { data: standings } = await supabaseAdmin.from('league_standings').select('league_instance_id').eq('team_id', team.id);
    if (standings && standings.length > 0) {
      const instanceId = standings[0].league_instance_id;
      const { data: instance } = await supabaseAdmin.from('league_instances').select('status, created_at').eq('id', instanceId).single();
      if (instance) {
        instanceStatus = instance.status;
        instanceCreatedAt = instance.created_at;
      }
      const { count } = await supabaseAdmin.from('league_standings').select('*', { count: 'exact', head: true }).eq('league_instance_id', instanceId);
      teamCount = count || 1;
    }

    // 2. Fetch all players (active and coaches) belonging to this team. STRICT FILTER APPLIED.
    const { data: players, error: playersError } = await supabaseAdmin
      .from('players')
      .select('id, name, age, ovr, is_nft_coach, traits, position, stats, stamina, lineup_status, lineup_slot, injury_matches_left, is_for_sale, is_retired, seasons_played')
      .eq('team_id', team.id);

    if (playersError) {
      return NextResponse.json({ error: 'Failed to fetch players' }, { status: 500 });
    }

    const safePlayers = (players || []).map(p => ({
      ...p,
      age: p.age ?? 18,
      is_for_sale: p.is_for_sale ?? false,
      is_retired: p.is_retired ?? false,
      seasons_played: p.seasons_played ?? 0
    }));

    return NextResponse.json({
      success: true,
      team,
      instanceStatus,
      instanceCreatedAt,
      teamCount,
      players: safePlayers
    });

  } catch (error: any) {
    console.error("My Team API Error:", error);
    return NextResponse.json(
      { error: 'Internal Server Error', details: error.message },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { supabase } from '@/lib/supabase';
import { cookies } from 'next/headers';

export interface SubmitLineupRequest {
  teamId: string;
}

const LEAGUE_OVR_CAP = 80;
const TAX_RATE_PER_OVR = 50;

export async function POST(req: Request) {
  try {
    const cookieStore = await cookies();
    const userId = cookieStore.get('tg_user_id')?.value;

    if (!userId) {
      return NextResponse.json({ error: 'Unauthorized: Missing valid session' }, { status: 401 });
    }

    const body: Partial<SubmitLineupRequest> = await req.json();
    const { teamId } = body;

    // 1. Validation
    if (!teamId) {
      return NextResponse.json(
        { error: 'Missing required payload field: teamId' },
        { status: 400 }
      );
    }

    // 2. Ownership Verification
    const { data: teamData, error: teamError } = await supabase
      .from('teams')
      .select('user_id')
      .eq('id', teamId)
      .single();

    if (teamError || !teamData) {
      return NextResponse.json(
        { error: 'Team not found or database read error' },
        { status: 404 }
      );
    }

    if (teamData.user_id !== userId) {
      return NextResponse.json(
        { error: 'Forbidden: You do not own this team' },
        { status: 403 }
      );
    }

    // 3. Compute Team Average OVR
    const { data: players, error: playersError } = await supabase
      .from('players')
      .select('ovr')
      .eq('team_id', teamId);

    if (playersError) {
      throw new Error(`Failed to fetch players: ${playersError.message}`);
    }

    let averageOvr = 50; // fallback base
    if (players && players.length > 0) {
      const sum = players.reduce((acc, p) => acc + p.ovr, 0);
      averageOvr = Math.round(sum / players.length);
    }

    // 4. Calculate Luxury Tax Penalty
    const tax = Math.max(0, (averageOvr - LEAGUE_OVR_CAP) * TAX_RATE_PER_OVR);

    // 5. Verify Balance and Execute Simulated Transaction
    if (tax > 0) {
      // Fetch user's current FanCoin wallet balance
      const { data: user, error: userError } = await supabase
        .from('users')
        .select('balance_fancoins')
        .eq('id', userId)
        .single();

      if (userError || !user) {
        return NextResponse.json(
          { error: 'User not found during economic validation' },
          { status: 404 }
        );
      }

      const currentBalance = Number(user.balance_fancoins) || 0;

      if (currentBalance < tax) {
        return NextResponse.json(
          { error: `Insufficient FanCoins to pay Luxury Tax. Required: ${tax}, Balance: ${currentBalance}` },
          { status: 400 }
        );
      }

      const newBalance = currentBalance - tax;

      // Preemptively deduct the tax (Step 1 of atomic flow)
      const { error: deductError } = await supabase
        .from('users')
        .update({ balance_fancoins: newBalance })
        .eq('id', userId);

      if (deductError) {
        throw new Error(`Failed to process Luxury Tax deduction: ${deductError.message}`);
      }

      // Flag the team as ready (Step 2 of atomic flow)
      const { error: readyError } = await supabase
        .from('teams')
        .update({ is_ready_for_match: true })
        .eq('id', teamId);

      if (readyError) {
        // Rollback: Refund the tax if marking the team fails
        console.error("Failed to mark team as ready. Initiating tax rollback...", readyError);
        await supabase
          .from('users')
          .update({ balance_fancoins: currentBalance })
          .eq('id', userId);

        throw new Error(`Failed to submit lineup state: ${readyError.message}. FanCoin tax refunded securely.`);
      }

    } else {
      // No tax due, bypass economic burn and simply mark state as ready
      const { error: readyError } = await supabase
        .from('teams')
        .update({ is_ready_for_match: true })
        .eq('id', teamId);

      if (readyError) {
        throw new Error(`Failed to submit lineup state: ${readyError.message}`);
      }
    }

    // 6. Return formatting Response
    return NextResponse.json({
      success: true,
      averageOvr,
      taxPaid: tax,
      message: tax > 0 ? `Lineup submitted. Paid ${tax} FanCoins in Luxury Tax.` : 'Lineup submitted securely. No Luxury Tax due.',
    });

  } catch (error: any) {
    console.error("Submit Lineup API Error:", error);
    return NextResponse.json(
      { error: 'Internal Server Error', details: error.message },
      { status: 500 }
    );
  }
}

