'use client';

import React, { useState } from 'react';
import { 
  FORMATION_LINKS, 
  getSlotCoords, 
  calculateLinkStrength, 
  getIdealLineForSlot,
  ChemistryRecord 
} from '@/app/utils/chemistry';

const TRAIT_COLORS: Record<string, { bg: string, border: string, text: string, short: string }> = {
  'Sniper': { bg: 'bg-teal-900/80', border: 'border-teal-500', text: 'text-teal-400', short: 'SN' },
  'Playmaker': { bg: 'bg-blue-900/80', border: 'border-blue-500', text: 'text-blue-400', short: 'PM' },
  'Wall': { bg: 'bg-purple-900/80', border: 'border-purple-500', text: 'text-purple-400', short: 'WL' },
  'Speedster': { bg: 'bg-orange-900/80', border: 'border-orange-500', text: 'text-orange-400', short: 'SP' },
  'Anchor': { bg: 'bg-indigo-900/80', border: 'border-indigo-500', text: 'text-indigo-400', short: 'AN' },
  'Poacher': { bg: 'bg-pink-900/80', border: 'border-pink-500', text: 'text-pink-400', short: 'PO' },
  'Engine': { bg: 'bg-yellow-900/80', border: 'border-yellow-500', text: 'text-yellow-400', short: 'EN' },
  'Leader': { bg: 'bg-red-900/80', border: 'border-red-500', text: 'text-red-400', short: 'LD' },
};

interface Player {
  id: string;
  position: string;
  lineup_slot?: string;
  lineup_status: string;
}

interface Props {
  formation: string;
  players: Player[];
  chemistryData?: Record<string, ChemistryRecord>; // key: `${id1}_${id2}` or similar
}

export function ChemistryOverlay({ formation, players, chemistryData }: Props) {
  const [showLegend, setShowLegend] = useState(false);
  const links = FORMATION_LINKS[formation as keyof typeof FORMATION_LINKS] || [];

  const getPlayerInSlot = (slotIndex: number) => {
    return players.find(p => parseInt(p.lineup_slot || '-1', 10) === slotIndex);
  };

  return (
    <div className="absolute inset-0 w-full h-full pointer-events-none z-20">

      {/* SVG for lines */}
      <svg 
        className="absolute inset-0 w-full h-full overflow-visible" 
      >
        <defs>
          <filter id="neon-glow" x="-50%" y="-50%" width="200%" height="200%">
            <feGaussianBlur stdDeviation="3" result="coloredBlur"/>
            <feMerge>
              <feMergeNode in="coloredBlur"/>
              <feMergeNode in="SourceGraphic"/>
            </feMerge>
          </filter>
        </defs>

        {links.map(([slot1, slot2], idx) => {
          const p1 = getPlayerInSlot(slot1);
          const p2 = getPlayerInSlot(slot2);

          if (!p1 || !p2) return null;

          const idealPos1 = getIdealLineForSlot(slot1, formation);
          const idealPos2 = getIdealLineForSlot(slot2, formation);
          const record = chemistryData ? chemistryData[`${p1.id}_${p2.id}`] : { matches_together: 50, sweat_points: 0 };
          const strength = calculateLinkStrength(p1 as any, idealPos1, p2 as any, idealPos2, record);

          if (strength === 'none') return null;

          const coords1 = getSlotCoords(slot1, formation);
          const coords2 = getSlotCoords(slot2, formation);

          let strokeColor = '';
          let strokeWidth = 2;
          let dasharray = '';
          let filter = '';

          if (strength === 'red') {
            strokeColor = '#ef4444'; // red-500
            strokeWidth = 1.5;
            dasharray = '4 4';
          } else if (strength === 'yellow') {
            strokeColor = '#eab308'; // yellow-500
            strokeWidth = 2.5;
          } else if (strength === 'green') {
            strokeColor = '#39ff14'; // Neon Green
            strokeWidth = 3;
            filter = 'url(#neon-glow)';
          }

          return (
            <line
              key={`${slot1}-${slot2}-${idx}`}
              x1={`${coords1.x}%`}
              y1={`${coords1.y}%`}
              x2={`${coords2.x}%`}
              y2={`${coords2.y}%`}
              stroke={strokeColor}
              strokeWidth={strokeWidth}
              strokeDasharray={dasharray}
              filter={filter}
              className="transition-all duration-500"
            />
          );
        })}
      </svg>

      {/* Compact Trait Nodes Overlay */}
      {players.filter(p => p.lineup_status === 'starting').map(p => {
        const slot = parseInt(p.lineup_slot || '-1', 10);
        if (slot < 0) return null;

        const coords = getSlotCoords(slot, formation);
        const hasTraits = (p as any).traits && (p as any).traits.length > 0;

        if (!hasTraits) return null;

        return (
          <div 
            key={p.id}
            className="absolute flex flex-col gap-0.5 z-30"
            style={{ 
              left: `calc(${coords.x}% + 18px)`, 
              top: `calc(${coords.y}% - 22px)` 
            }}
          >
            {(p as any).traits.map((trait: string, idx: number) => {
              const style = TRAIT_COLORS[trait] || { bg: 'bg-gray-900/80', border: 'border-gray-500', text: 'text-gray-400', short: trait.substring(0, 2).toUpperCase() };
              return (
                <div 
                  key={idx}
                  title={trait}
                  className={`w-5 h-5 flex items-center justify-center rounded-full border ${style.bg} ${style.border} ${style.text} text-[8px] font-black shadow-[0_0_8px_rgba(0,0,0,0.8)] backdrop-blur-sm`}
                >
                  {style.short}
                </div>
              );
            })}
          </div>
        );
      })}
    </div>
  );
}

'use client';

import { useState, useContext, useEffect } from 'react';
import { TelegramAuthContext } from '@/components/providers/TelegramAuthProvider';
import { LanguageContext } from '@/components/LanguageContext';
import { dict } from '@/lib/dictionaries';
import { supabase } from '@/lib/supabase';

export function FitnessSyncWidget() {
  const { userId, isAuthenticated } = useContext(TelegramAuthContext);
  const { language } = useContext(LanguageContext);
  const t = dict[language as keyof typeof dict];

  const [stepsInput, setStepsInput] = useState('');
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncState, setSyncState] = useState<'idle' | 'loading' | 'success'>('idle');
  const [dailySteps, setDailySteps] = useState(0);
  const [limitReached, setLimitReached] = useState(false);

  const MAX_STEPS = 20000;

  useEffect(() => {
    const fetchState = async () => {
      if (!userId) return;
      const { data } = await supabase.from('users').select('daily_steps_logged, last_sync_date').eq('id', userId).single();
      if (data) {
        const tzDate = new Date().toISOString().split('T')[0];
        if (data.last_sync_date === tzDate) {
           setDailySteps(data.daily_steps_logged || 0);
           setLimitReached((data.daily_steps_logged || 0) >= MAX_STEPS);
        } else {
           setDailySteps(0);
           setLimitReached(false);
        }
      }
    };
    if (isAuthenticated) fetchState();
  }, [userId, isAuthenticated]);

  const handleSync = async () => {
    const steps = parseInt(stepsInput, 10);
    if (!userId || isNaN(steps) || steps <= 0 || limitReached) return;

    setIsSyncing(true);
    setSyncState('loading');

    const tzDate = new Date().toISOString().split('T')[0];

    try {
      const res = await fetch('/api/fitness/sync', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, steps, timezoneDate: tzDate })
      });
      const data = await res.json();

      if (res.ok && data.success) {
        setDailySteps(data.daily_steps_logged);
        setLimitReached(data.limit_reached);
        setSyncState('success');
        setStepsInput('');

        if (data.earned_tp > 0) {
          window.dispatchEvent(new Event('balanceUpdated'));
        }

        setTimeout(() => setSyncState('idle'), 2000);
      } else {
        setSyncState('idle');
      }
    } catch (e) {
      console.error(e);
      setSyncState('idle');
    } finally {
      setIsSyncing(false);
    }
  };

  const progressPercent = Math.min(100, (dailySteps / MAX_STEPS) * 100);
  const isWarning = progressPercent >= 80;
  const isDanger = progressPercent >= 100;

  const barColor = isDanger 
    ? 'bg-red-500 shadow-[0_0_15px_rgba(239,68,68,0.8)]' 
    : isWarning 
      ? 'bg-orange-500 shadow-[0_0_15px_rgba(249,115,22,0.8)]' 
      : 'bg-neon-cyan shadow-[0_0_15px_rgba(0,240,255,0.8)]';

  const buttonClass = syncState === 'success' 
    ? 'bg-neon-green text-black shadow-[0_0_20px_rgba(57,255,20,0.8)] border-transparent'
    : syncState === 'loading'
      ? 'bg-transparent border border-neon-cyan text-neon-cyan'
      : limitReached
        ? 'bg-gray-800 text-gray-500 border-gray-700 cursor-not-allowed'
        : 'bg-neon-pink/10 border border-neon-pink text-neon-pink hover:bg-neon-pink hover:text-white shadow-[0_0_15px_rgba(255,0,60,0.4)] hover:shadow-[0_0_25px_rgba(255,0,60,0.8)]';

  return (
    <div className="w-full bg-black/60 backdrop-blur-md rounded-2xl border border-neon-cyan/30 p-6 flex flex-col gap-6 relative overflow-hidden shadow-[0_10px_30px_rgba(0,0,0,0.5)]">
      {/* Background glow */}
      <div className="absolute -top-10 -right-10 w-40 h-40 bg-neon-cyan/10 rounded-full blur-3xl pointer-events-none"></div>

      <div className="relative z-10 flex flex-col gap-2">
        <div className="flex justify-between items-end">
          <h2 className="text-xl font-bold font-orbitron tracking-widest uppercase text-white drop-shadow-[0_0_5px_rgba(255,255,255,0.5)]">Step Sync</h2>
          <span className="text-[10px] uppercase font-bold text-gray-400 tracking-wider">Daily Limit: 20k</span>
        </div>

        {/* Progress Bar Container */}
        <div className="w-full h-3 bg-gray-900 rounded-full overflow-hidden border border-gray-800 relative shadow-inner">
          <div 
            className={`h-full transition-all duration-1000 ease-out ${barColor}`} 
            style={{ width: `${progressPercent}%` }}
          />
        </div>
        <div className="flex justify-between text-xs font-mono">
          <span className={`${isDanger ? 'text-red-400' : isWarning ? 'text-orange-400' : 'text-neon-cyan'}`}>
            {dailySteps.toLocaleString()} logged
          </span>
          <span className="text-gray-500">{(MAX_STEPS - dailySteps).toLocaleString()} remaining</span>
        </div>
      </div>

      {/* Terminal Input */}
      <div className="relative z-10 bg-black/80 border border-gray-700 rounded-lg p-1 flex items-center shadow-inner group focus-within:border-neon-cyan transition-colors">
        <div className="px-3 text-neon-cyan font-mono text-sm opacity-50 select-none">{'>'}</div>
        <input 
          type="number" 
          value={stepsInput}
          onChange={(e) => setStepsInput(e.target.value)}
          placeholder="ENTER_STEPS..."
          disabled={limitReached || isSyncing}
          className="bg-transparent text-white font-mono placeholder-gray-600 focus:outline-none w-full py-3"
        />
        {stepsInput && !isSyncing && !limitReached && (
           <div className="pr-4 text-[10px] text-gray-500 font-bold tracking-widest whitespace-nowrap">
             ≈ {Math.floor(parseInt(stepsInput, 10) / 100) || 0} TP
           </div>
        )}
      </div>

      {/* Action Button */}
      <button 
        onClick={handleSync}
        disabled={isSyncing || limitReached || !stepsInput}
        className={`relative z-10 w-full py-4 rounded-lg font-bold uppercase tracking-widest transition-all duration-300 overflow-hidden ${buttonClass}`}
      >
        {syncState === 'loading' ? (
          <span className="flex items-center justify-center gap-2">
            <span className="w-4 h-4 border-2 border-neon-cyan border-t-transparent rounded-full animate-spin"></span>
            SYNCING_DATA...
          </span>
        ) : syncState === 'success' ? (
          <span className="tracking-widest">DATA_UPLOADED</span>
        ) : limitReached ? (
          <span>LIMIT_REACHED</span>
        ) : (
          <span>INITIATE_SYNC</span>
        )}
      </button>
    </div>
  );
}

