'use client';

import { useEffect, useState } from 'react';
import { MatchEvent } from '@/app/utils/matchEngine';
import { markMatchAsViewed } from '@/app/actions/matchActions';
import { Activity, Shield, Target, AlertCircle, RefreshCcw } from 'lucide-react';

export interface MatchReport {
  id: string;
  home_team_id: string;
  away_team_id: string;
  home_team_name: string;
  away_team_name: string;
  home_score: number;
  away_score: number;
  events: MatchEvent[];
  round_number?: number;
  stamina_drain?: {
    home: Record<string, number>;
    away: Record<string, number>;
  };
}

interface MatchReportModalProps {
  report: MatchReport;
  userTeamId: string;
  onClose: () => void;
}

export function MatchReportModal({ report, userTeamId, onClose }: MatchReportModalProps) {
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    document.body.style.overflow = 'hidden';
    return () => { document.body.style.overflow = 'auto'; };
  }, []);

  const handleAccept = async () => {
    setIsSubmitting(true);
    await markMatchAsViewed(report.id);
    setIsSubmitting(false);
    onClose();
  };

  const isHome = userTeamId === report.home_team_id;
  const isWin = isHome ? report.home_score > report.away_score : report.away_score > report.home_score;
  const isDraw = report.home_score === report.away_score;

  const resultColor = isDraw ? 'text-gray-400' : isWin ? 'text-neon-green' : 'text-red-500';
  const resultText = isDraw ? 'DRAW' : isWin ? 'VICTORY' : 'DEFEAT';

  const getEventIcon = (type: string) => {
    if (type === 'goal') return <Target className="w-4 h-4 text-neon-green" />;
    if (type === 'save') return <Shield className="w-4 h-4 text-neon-cyan" />;
    if (type === 'yellow_card') return <AlertCircle className="w-4 h-4 text-yellow-500" />;
    if (type === 'red_card') return <AlertCircle className="w-4 h-4 text-red-500" />;
    if (type === 'injury') return <Activity className="w-4 h-4 text-red-500" />;
    if (type === 'substitution') return <RefreshCcw className="w-4 h-4 text-blue-400" />;
    return <AlertCircle className="w-4 h-4 text-gray-500" />;
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/90 backdrop-blur-md">
      <div className="w-full max-w-md bg-gray-900 border-2 border-neon-cyan rounded-xl shadow-[0_0_40px_rgba(0,240,255,0.2)] overflow-hidden flex flex-col relative animate-in fade-in zoom-in duration-300">

        {/* Header */}
        <div className="bg-gradient-to-b from-neon-cyan/20 to-transparent p-6 text-center border-b border-neon-cyan/30 relative">
          <div className={`text-sm font-black uppercase tracking-widest mb-2 ${resultColor} drop-shadow-[0_0_10px_currentColor]`}>
            {resultText}
          </div>

          <div className="flex justify-between items-center px-4">
            <div className={`flex-1 text-right text-lg font-black uppercase truncate pr-4 ${isHome ? 'text-neon-cyan' : 'text-gray-400'}`}>
              {report.home_team_name}
            </div>
            <div className="flex flex-col items-center shrink-0 w-24">
              <div className="text-4xl font-black text-white tracking-tighter">
                {report.home_score} - {report.away_score}
              </div>
            </div>
            <div className={`flex-1 text-left text-lg font-black uppercase truncate pl-4 ${!isHome ? 'text-neon-cyan' : 'text-gray-400'}`}>
              {report.away_team_name}
            </div>
          </div>
        </div>

        {/* Timeline */}
        <div className="flex-1 overflow-y-auto max-h-[40vh] p-4 bg-black/50 custom-scrollbar">
          <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest border-b border-gray-800 pb-2 mb-4 text-center">
            Match Events
          </h3>

          {report.events?.length === 0 ? (
            <div className="text-center text-sm text-gray-600 font-mono py-8">No significant events</div>
          ) : (
            <div className="flex flex-col gap-3 relative">
              <div className="absolute left-1/2 top-0 bottom-0 w-px bg-gray-800 -translate-x-1/2" />

              {report.events?.map((ev, idx) => {
                const evTeamId = ev.team === 'home' ? report.home_team_id : report.away_team_id;
                const isHomeEvent = evTeamId === report.home_team_id;
                const isUserTeam = evTeamId === userTeamId;

                return (
                  <div key={idx} className="flex items-center w-full relative z-10 my-1">
                    <div className="flex-1 pr-4 flex justify-end items-center">
                      {isHomeEvent && (
                        <div className={`flex flex-col text-right p-2 rounded-lg border w-[95%] ${isUserTeam ? 'bg-neon-cyan/10 border-neon-cyan/30' : 'bg-gray-800/80 border-gray-700'}`}>
                           <div className="flex items-center justify-end gap-1 mb-1">
                              <span className={`text-xs font-bold truncate ${isUserTeam ? 'text-white' : 'text-gray-300'}`}>{ev.player_name}</span>
                              {ev.player_id && ev.player_id !== 'sys' && (
                                <img 
                                  src={`https://api.dicebear.com/9.x/micah/svg?seed=${ev.player_id}&backgroundColor=transparent`} 
                                  alt="avatar" 
                                  className="w-4 h-4 rounded-full bg-black/50" 
                                />
                              )}
                              {getEventIcon(ev.type)}
                           </div>
                           <span className="text-[9px] text-gray-400 whitespace-normal line-clamp-2 leading-tight">{ev.details}</span>
                        </div>
                      )}
                    </div>

                    <div className="w-8 h-8 rounded-full bg-black border border-gray-700 flex items-center justify-center shrink-0 z-20 shadow-[0_0_10px_rgba(0,0,0,0.5)]">
                      <span className="text-[10px] font-orbitron font-bold text-neon-cyan">{ev.minute}'</span>
                    </div>

                    <div className="flex-1 pl-4 flex justify-start items-center">
                      {!isHomeEvent && (
                        <div className={`flex flex-col text-left p-2 rounded-lg border w-[95%] ${isUserTeam ? 'bg-neon-cyan/10 border-neon-cyan/30' : 'bg-gray-800/80 border-gray-700'}`}>
                           <div className="flex items-center justify-start gap-1 mb-1">
                              {getEventIcon(ev.type)}
                              {ev.player_id && ev.player_id !== 'sys' && (
                                <img 
                                  src={`https://api.dicebear.com/9.x/micah/svg?seed=${ev.player_id}&backgroundColor=transparent`} 
                                  alt="avatar" 
                                  className="w-4 h-4 rounded-full bg-black/50" 
                                />
                              )}
                              <span className={`text-xs font-bold truncate ${isUserTeam ? 'text-white' : 'text-gray-300'}`}>{ev.player_name}</span>
                           </div>
                           <span className="text-[9px] text-gray-400 whitespace-normal line-clamp-2 leading-tight">{ev.details}</span>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* Stamina Drain Summary */}
        <div className="px-4 py-3 bg-gray-900 border-t border-gray-800 flex justify-center">
          <div className="flex items-center gap-2 text-xs text-gray-400">
            <Activity className="w-4 h-4 text-neon-pink" />
            <span>Squad Stamina Drain: <strong className="text-neon-pink">~20%</strong></span>
          </div>
        </div>

        {/* Footer */}
        <div className="p-4 border-t border-gray-800 bg-gray-900">
          <button 
            onClick={handleAccept}
            disabled={isSubmitting}
            className="w-full py-4 rounded-lg bg-neon-cyan text-black font-black uppercase tracking-widest hover:bg-white hover:shadow-[0_0_20px_rgba(0,240,255,0.5)] transition-all disabled:opacity-50"
          >
            {isSubmitting ? 'Processing...' : 'Accept Report'}
          </button>
        </div>

      </div>
    </div>
  );
}

'use client';

import { useState, useContext } from 'react';
import { LanguageContext } from '@/components/LanguageContext';
import { dict } from '@/lib/dictionaries';

interface OnboardingFlowProps {
  userId: string;
  onSuccess: () => void;
}

export function OnboardingFlow({ userId, onSuccess }: OnboardingFlowProps) {
  const [step, setStep] = useState<1 | 2>(1);
  const { language } = useContext(LanguageContext);
  const t = dict[language as keyof typeof dict];
  const headerFontClass = language === 'ru' ? 'font-russo' : 'font-orbitron';
  const buttonFontClass = language === 'ru' ? 'font-russo' : 'font-orbitron';

  const [teamNameInput, setTeamNameInput] = useState('');
  const [isCreatingTeam, setIsCreatingTeam] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const handleCreateTeam = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!userId || !teamNameInput.trim()) return;

    setIsCreatingTeam(true);
    setErrorMsg(null);
    try {
      const res = await fetch('/api/team/create', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId, teamName: teamNameInput.trim() }),
      });

      if (res.ok) {
        onSuccess();
      } else {
        const err = await res.json();
        setErrorMsg(err.error || 'Failed to create team');
      }
    } catch (error: any) {
      setErrorMsg(error.message || 'Network error');
    } finally {
      setIsCreatingTeam(false);
    }
  };

  if (step === 1) {
    return (
      <div className="flex flex-col flex-1 p-6 gap-8 justify-center min-h-screen bg-space-dark items-center text-center">
        <div className="w-24 h-24 rounded-full border-4 border-neon-cyan mb-4 flex items-center justify-center bg-black/50 shadow-[0_0_30px_rgba(0,240,255,0.4)]">
          <span className={`text-4xl text-neon-cyan ${headerFontClass}`}>FM</span>
        </div>
        <h1 className={`text-3xl font-bold text-white mb-2 tracking-wide ${headerFontClass}`}>
          {t.welcome}
        </h1>
        <p className="text-gray-300 leading-relaxed mb-8 text-base px-2">
          {t.onboarding_welcome}
        </p>
        <button 
          onClick={() => setStep(2)}
          className={`w-full max-w-xs py-4 rounded-lg font-bold text-black uppercase tracking-wider transition-all duration-300 bg-neon-cyan hover:bg-white hover:text-neon-cyan shadow-[0_0_20px_rgba(0,240,255,0.6)] ${buttonFontClass}`}
        >
          {t.onboarding_next}
        </button>
      </div>
    );
  }

  return (
    <div className="flex flex-col flex-1 p-6 gap-8 justify-center min-h-screen bg-space-dark">
      <div className="bg-black/60 backdrop-blur-md p-8 rounded-2xl border border-neon-pink/50 shadow-[0_0_30px_rgba(255,0,60,0.2)]">
        <h1 className={`text-2xl font-bold text-white mb-2 text-center uppercase ${headerFontClass}`}>{t.onboarding_create_title}</h1>
        <p className="text-gray-400 text-center mb-8 text-sm">{t.onboarding_create_desc}</p>

        <form onSubmit={handleCreateTeam} className="flex flex-col gap-5">
          <div>
            <label className="text-xs text-neon-cyan uppercase tracking-widest font-bold mb-2 block">{t.onboarding_franchise_name}</label>
            <input 
              type="text" 
              value={teamNameInput}
              onChange={(e) => setTeamNameInput(e.target.value)}
              placeholder={t.onboarding_placeholder}
              required
              maxLength={30}
              className="w-full bg-black/50 border border-gray-700 text-white rounded-lg p-3 focus:outline-none focus:border-neon-cyan focus:ring-1 focus:ring-neon-cyan transition-all"
            />
          </div>

          {errorMsg && (
            <div className="text-red-400 text-xs text-center font-bold bg-red-900/30 p-2 rounded">
              {errorMsg}
            </div>
          )}

          <button 
            type="submit"
            disabled={isCreatingTeam || !teamNameInput.trim()}
            className={`w-full py-4 rounded-lg font-bold text-black uppercase tracking-wider transition-all duration-300 mt-2 ${buttonFontClass} ${
              isCreatingTeam || !teamNameInput.trim()
                ? 'bg-gray-600 cursor-not-allowed opacity-70'
                : 'bg-neon-pink hover:bg-white hover:text-neon-pink hover:shadow-[0_0_20px_rgba(255,0,60,0.6)] shadow-[0_0_10px_rgba(255,0,60,0.4)]'
            }`}
          >
            {isCreatingTeam ? t.onboarding_drafting : t.onboarding_submit}
          </button>
        </form>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { X, Activity, Zap, User, Crosshair, ChevronRight } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { bulkTrainPlayer } from '@/app/actions/playerActions';
import { healPlayer } from '@/app/actions/baseActions';
import { renamePlayerAction, retirePlayerToAcademy, quickSellPlayer } from '@/app/actions/teamActions';
import { InfoPopover } from '@/components/ui/InfoPopover';
import Link from 'next/link';
import { listPlayerAction } from '@/app/actions/marketActions';
import toast from 'react-hot-toast';
import { Radar, RadarChart, PolarGrid, PolarAngleAxis, ResponsiveContainer, PolarRadiusAxis } from 'recharts';

// ─────────────────────────────────────────────────────────────────────────────
// Types
// ─────────────────────────────────────────────────────────────────────────────

interface PlayerStats {
  pace:      number;
  shooting:  number;
  passing:   number;
  defending: number;
  physical:  number;
}

interface Player {
  id:                   string;
  name:                 string;
  age:                  number;
  ovr:                  number;
  potential_limit:      number;
  position:             string;
  stamina:              number;
  stats:                PlayerStats;
  traits?:              string[];
  is_injured?:          boolean;
  injury_matches_left?: number;
  lineup_status:        string;
  is_for_sale?:         boolean;
  is_retired?:          boolean;
  seasons_played?:      number;
}

interface Props {
  player:          Player;
  userId:          string;
  onClose:         () => void;
  onTrainSuccess:  (updatedPlayer: Player, newBalance: number) => void;
}

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────

/** Exponential building cost mirror (for display only) */
function buildingUpgradeCost(level: number) {
  return Math.floor(500 * Math.pow(level, 1.5));
}


// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

export function PlayerProfileModal({ player, userId, onClose, onTrainSuccess }: Props) {
  const [fancoins,      setFancoins]      = useState<number>(0);
  const [sweatPoints,   setSweatPoints]   = useState<number>(0);
  const [medicalLevel,  setMedicalLevel]  = useState<number>(1);
  const [stadiumLevel,  setStadiumLevel]  = useState<number>(1);
  const [isLoadingData, setIsLoadingData] = useState(true);
  const [isHealing,     setIsHealing]     = useState(false);
  const [errorMsg,      setErrorMsg]      = useState<string | null>(null);

  const [sellMode,      setSellMode]      = useState(false);
  const [sellPrice,     setSellPrice]     = useState('');
  const [isPendingSell, startTransition]  = React.useTransition();

  const [renameMode,      setRenameMode]      = useState(false);
  const [newName,         setNewName]         = useState(player.name);
  const [isPendingRename, startTransitionRename] = React.useTransition();

  const [isPendingRetire, startTransitionRetire] = React.useTransition();
  const [isPendingQuickSell, startTransitionQuickSell] = React.useTransition();

  // ── Load balances + medical level ─────────────────────────────────────────

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [infraRes, userRes] = await Promise.all([
          fetch(`/api/infrastructure?userId=${userId}`),
          fetch(`/api/user/me?userId=${userId}`),
        ]);

        if (infraRes.ok) {
          const infraData = await infraRes.json();
          setMedicalLevel(infraData.infrastructure?.medical_center_level ?? 1);
          setStadiumLevel(infraData.infrastructure?.stadium_level ?? 1);
        }
        if (userRes.ok) {
          const userData = await userRes.json();
          setFancoins(userData.user?.balance_fancoins ?? 0);
          setSweatPoints(userData.user?.sweat_points ?? 0);
        }
      } catch (err) {
        console.error('[PlayerProfileModal] Failed to fetch data:', err);
      } finally {
        setIsLoadingData(false);
      }
    };
    fetchData();
  }, [userId]);

  // ── Computed ──────────────────────────────────────────────────────────────

  const stats = player.stats || { pace: 50, shooting: 50, passing: 50, defending: 50, physical: 50 };

  const cost = Math.max(0, 100 - (player.stamina ?? 100));
  const canAffordHeal = sweatPoints >= cost;

  // ── Heal handler ─────────────────────────────────────────────────────────

  const handleHeal = async () => {
    if (!canAffordHeal || isHealing) return;
    setIsHealing(true);
    setErrorMsg(null);

    try {
      const res = await healPlayer(userId, player.id);
      if (res.success) {
        const newBal = res.new_balance ?? sweatPoints - cost;
        setSweatPoints(newBal);
        window.dispatchEvent(new Event('balanceUpdated'));
        const updatedPlayer = { ...player, stamina: 100, is_injured: false, injury_matches_left: 0 };
        onTrainSuccess(updatedPlayer as Player, newBal);
      } else {
        setErrorMsg(res.error ?? 'Healing failed');
      }
    } catch {
      setErrorMsg('Network error occurred.');
    } finally {
      setIsHealing(false);
    }
  };

  // ── Sell handler ─────────────────────────────────────────────────────────
  const handleSell = () => {
    const price = parseFloat(sellPrice);
    if (isNaN(price) || price <= 0) {
      toast.error('Введите корректную цену в TON');
      return;
    }
    const fee = stadiumLevel * 250;
    if (fancoins < fee) {
      toast.error(`Недостаточно FanCoins для налога. Нужно: ${fee} FC`);
      return;
    }
    if (player.lineup_status === 'starting' || player.lineup_status === 'bench') {
      toast.error('Игрок в составе. Сначала переведите его в резерв.');
      return;
    }

    startTransition(async () => {
      const res = await listPlayerAction(player.id, price);
      if (res.success) {
        toast.success(`Игрок выставлен на рынок за ${price} TON`);
        window.dispatchEvent(new Event('balanceUpdated'));
        onClose(); // Close modal on success
      } else {
        toast.error(res.error || 'Ошибка при выставлении на рынок');
      }
    });
  };

  // ── Rename handler ───────────────────────────────────────────────────────
  const handleRename = () => {
    const trimmed = newName.trim();
    if (!trimmed || trimmed.length < 3) {
      toast.error('Имя должно содержать минимум 3 символа');
      return;
    }
    if (fancoins < 1000) {
      toast.error('Недостаточно FanCoins для переименования (Нужно: 1000 FC)');
      return;
    }

    startTransitionRename(async () => {
      const res = await renamePlayerAction(player.id, trimmed);
      if (res.success) {
        toast.success(`Игрок успешно переименован в ${trimmed}!`);
        window.dispatchEvent(new Event('balanceUpdated'));
        setFancoins(prev => prev - 1000);
        player.name = trimmed; // optimistic update
        setRenameMode(false);
      } else {
        toast.error(res.error || 'Ошибка при переименовании');
      }
    });
  };

  // ── Retire handler ───────────────────────────────────────────────────────
  const handleRetire = () => {
    startTransitionRetire(async () => {
      const res = await retirePlayerToAcademy(player.id);
      if (res.success) {
        toast.success(`Перк тренера успешно применен к Академии!`);
        onClose(); // Close modal on success (player is burnt)
      } else {
        toast.error(res.error || 'Ошибка при применении перка');
      }
    });
  };

  // ── Quick Sell handler ───────────────────────────────────────────────────
  const handleQuickSell = () => {
    if (confirm(`Вы уверены, что хотите продать ${player.name} системе? Это действие нельзя отменить.`)) {
      startTransitionQuickSell(async () => {
        const res = await quickSellPlayer(player.id);
        if (res.success) {
          toast.success(`Игрок успешно продан системе за ${res.payout} FC!`);
