'use client';

import React, { useState } from 'react';
import { hardResetUserTeam } from '@/app/actions/adminActions';
import { useTelegramAuth } from '@/components/providers/TelegramAuthProvider';
import toast from 'react-hot-toast';

export function HardResetButton() {
  const [isResetting, setIsResetting] = useState(false);
  const { userId } = useTelegramAuth();

  const handleHardReset = async () => {
    if (!userId) {
      toast.error('User not authenticated');
      return;
    }

    if (!window.confirm("WARNING: This will permanently delete your entire franchise (Team, Players, Infrastructure, Standings). The app will reload and you will create a new team from scratch. Are you sure?")) {
      return;
    }

    setIsResetting(true);
    try {
      const res = await hardResetUserTeam(userId);
      if (res.success) {
        toast.success(res.message || 'Hard reset successful');
        // Wait a moment then reload to trigger onboarding flow
        setTimeout(() => {
          window.location.href = '/';
        }, 1500);
      } else {
        toast.error(res.error || 'Hard reset failed');
      }
    } catch (err: any) {
      toast.error('Network error during reset');
    } finally {
      setIsResetting(false);
    }
  };

  return (
    <button
      onClick={handleHardReset}
      disabled={isResetting}
      className={`mt-4 px-6 py-3 rounded-lg font-black uppercase tracking-widest text-xs transition-all w-full flex items-center justify-center gap-2 ${
        isResetting
          ? 'bg-red-900/50 text-red-500 cursor-not-allowed'
          : 'bg-red-900/20 text-red-500 border border-red-500 hover:bg-red-500 hover:text-white shadow-[0_0_15px_rgba(239,68,68,0.2)]'
      }`}
    >
      {isResetting ? 'RESETTING...' : '⚡ HARD RESET ROSTER'}
    </button>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Clock } from 'lucide-react';
import { dict } from '@/lib/dictionaries';

interface Props {
  nextMatchTime?: string;
  language?: string;
}

export function NextMatchCountdown({ nextMatchTime, language = 'en' }: Props) {
  const t = dict[language as keyof typeof dict];
  const [minutesLeft, setMinutesLeft] = useState(0);
  const [secondsLeft, setSecondsLeft] = useState(0);
  const [targetHour, setTargetHour] = useState('');

  useEffect(() => {
    const updateCountdown = () => {
      const now = new Date();
      const nextHour = new Date();
      nextHour.setHours(now.getHours() + 1, 0, 0, 0);

      const diff = nextHour.getTime() - now.getTime();
      const m = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
      const s = Math.floor((diff % (1000 * 60)) / 1000);

      setMinutesLeft(m);
      setSecondsLeft(s);
      setTargetHour(`${nextHour.getHours().toString().padStart(2, '0')}:00`);
    };

    updateCountdown();
    const interval = setInterval(updateCountdown, 1000);
    return () => clearInterval(interval);
  }, []);

  const progressPct = ((60 - minutesLeft) / 60) * 100;

  return (
    <div className="bg-black/40 backdrop-blur-md border border-cyan-500/30 rounded-2xl p-4 flex flex-col gap-2 shadow-[0_0_20px_rgba(6,182,212,0.15)]">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2 text-cyan-400">
          <Clock className="w-4 h-4 animate-pulse" />
          <span className="text-[10px] font-bold uppercase tracking-[0.2em]">{t.next_fixture || 'NEXT FIXTURE'}</span>
        </div>
        <span className="text-sm font-black text-white font-orbitron drop-shadow-[0_0_5px_rgba(6,182,212,0.5)]">
          {targetHour}
        </span>
      </div>

      <div className="w-full h-1.5 bg-gray-800 rounded-full overflow-hidden mt-1 relative">
        <div 
          className="h-full bg-cyan-400 shadow-[0_0_10px_rgba(34,211,238,0.8)] transition-all duration-1000 ease-linear" 
          style={{ width: `${progressPct}%` }}
        />
      </div>

      <div className="flex justify-between items-center mt-1">
        <span className="text-[9px] text-gray-500 uppercase tracking-widest">{t.simulating_in || 'Simulating in'}</span>
        <span className="text-[10px] font-bold text-cyan-300 font-mono">
          {minutesLeft.toString().padStart(2, '0')}:{secondsLeft.toString().padStart(2, '0')}
        </span>
      </div>
    </div>
  );
}

