'use client';

import { createContext, useContext, useState, useEffect, useCallback, ReactNode } from 'react';
import { createClient } from '@supabase/supabase-js';

// ─────────────────────────────────────────────────────────────────────────────
// PaddingContext — controls 60px top padding for TMA fullscreen mode.
// Telegram's system UI (close button, ⋮ menu) overlaps our content in
// fullscreen mode. This context lets the user toggle a safe-area padding.
//
// Storage strategy:
//   1. localStorage — instant, no flash on mount
//   2. DB (users.tma_padding_enabled) — persists across devices/reinstalls
// ─────────────────────────────────────────────────────────────────────────────
const STORAGE_KEY = 'fm_tma_padding';
const PADDING_PX = 60;

interface PaddingContextValue {
  paddingEnabled: boolean;
  paddingStyle: { paddingTop: string };
  togglePadding: () => void;
  setUserId: (id: string) => void;
}

const PaddingContext = createContext<PaddingContextValue>({
  paddingEnabled: true,
  paddingStyle: { paddingTop: `${PADDING_PX}px` },
  togglePadding: () => {},
  setUserId: () => {},
});

export function usePadding() {
  return useContext(PaddingContext);
}

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

async function persistPadding(userId: string | null, enabled: boolean) {
  if (!userId) return;
  try {
    await supabase.rpc('save_padding_preference', { p_user_id: userId, p_enabled: enabled });
  } catch (e) {
    console.warn('[PaddingContext] Failed to persist preference:', e);
  }
}

export function PaddingProvider({ children }: { children: ReactNode }) {
  // Default TRUE — safer on first launch inside Telegram
  const [paddingEnabled, setPaddingEnabled] = useState(true);
  const [userId, setUserIdState] = useState<string | null>(null);
  const [hydrated, setHydrated] = useState(false);

  // ── Fast hydration from localStorage ─────────────────────────────────────
  useEffect(() => {
    const cached = localStorage.getItem(STORAGE_KEY);
    setTimeout(() => {
      if (cached !== null) {
        setPaddingEnabled(cached === 'true');
      }
      setHydrated(true);
    }, 0);
  }, []);

  // ── DB sync when userId becomes available ─────────────────────────────────
  const setUserId = useCallback(async (id: string) => {
    setUserIdState(id);
    try {
      const { data } = await supabase
        .from('users')
        .select('tma_padding_enabled')
        .eq('id', id)
        .single();
      if (data?.tma_padding_enabled !== undefined && data.tma_padding_enabled !== null) {
        setPaddingEnabled(data.tma_padding_enabled);
        localStorage.setItem(STORAGE_KEY, String(data.tma_padding_enabled));
      }
    } catch (e) {
      console.warn('[PaddingContext] DB sync failed, using localStorage.');
    }
  }, []);

  const togglePadding = useCallback(() => {
    setPaddingEnabled(prev => {
      const next = !prev;
      localStorage.setItem(STORAGE_KEY, String(next));
      persistPadding(userId, next);
      return next;
    });
  }, [userId]);

  if (!hydrated) return null;

  return (
    <PaddingContext.Provider
      value={{
        paddingEnabled,
        paddingStyle: { paddingTop: paddingEnabled ? `${PADDING_PX}px` : '0px' },
        togglePadding,
        setUserId,
      }}
    >
      {children}
    </PaddingContext.Provider>
  );
}

'use client';

import { createContext, useEffect, useState, ReactNode, useContext } from 'react';
import { LanguageContext } from '@/components/LanguageContext';

interface TelegramAuthContextType {
  isAuthenticated: boolean;
  userId: string | null;
  isLoading: boolean;
  error: string | null;
}

export const TelegramAuthContext = createContext<TelegramAuthContextType>({
  isAuthenticated: false,
  userId: null,
  isLoading: true,
  error: null,
});

export const useTelegramAuth = () => useContext(TelegramAuthContext);

export function TelegramAuthProvider({ children }: { children: ReactNode }) {
  const [isMounted, setIsMounted] = useState(false);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [userId, setUserId] = useState<string | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const { setLanguage } = useContext(LanguageContext);

  useEffect(() => {
    setTimeout(() => {
      setIsMounted(true);
    }, 0);

    const authenticate = async () => {
      try {
        if (typeof window !== 'undefined') {
          const twaModule = await import('@twa-dev/sdk');
          const WebApp = twaModule.default;

          WebApp.ready();
          WebApp.expand();
          try {
            if (WebApp.requestFullscreen) {
              WebApp.requestFullscreen();
            }
          } catch (e) {
            console.warn("requestFullscreen unsupported", e);
          }
          try {
            if (WebApp.setHeaderColor) {
              WebApp.setHeaderColor('#060913');
            }
          } catch (e) {}
          try {
            if (WebApp.setBackgroundColor) {
              WebApp.setBackgroundColor('#060913');
            }
          } catch (e) {}
          const initData = WebApp.initData;

          const lang = WebApp.initDataUnsafe?.user?.language_code;
          const photoUrl = WebApp.initDataUnsafe?.user?.photo_url;
          if (lang && lang.startsWith('ru')) {
            setLanguage('ru');
          }

          if (!initData) {
            console.warn("No Telegram initData found. Running outside of Telegram environment.");
            setIsLoading(false);
            return;
          }

          // Send initData to our secure API route to validate signature and set HttpOnly cookie
          const response = await fetch('/api/auth/telegram', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
            },
            body: JSON.stringify({ initData, photoUrl }),
          });

          if (!response.ok) {
            let errorMsg = 'Failed to authenticate with backend servers';
            try {
              const errData = await response.json();
              if (errData.error) errorMsg = errData.error;
            } catch (e) {}

            if (errorMsg === 'Session expired') {
              errorMsg = 'Session expired. Please completely close the Mini App (swipe down) and reopen it.';
            }
            throw new Error(errorMsg);
          }

          const data = await response.json();
          setIsAuthenticated(true);
          setUserId(data.user_id);
        }
      } catch (err: any) {
        console.error("Telegram Auth Initialization Error:", err);
        setError(err.message || 'Authentication sequence failed');
      } finally {
        setIsLoading(false);
      }
    };

    authenticate();
  }, [setLanguage]);

  if (!isMounted || isLoading) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center min-h-screen bg-space-dark relative overflow-hidden">
        <style>{`
          @keyframes spin-reverse {
            from { transform: rotate(360deg); }
            to { transform: rotate(0deg); }
          }
          .animate-spin-slow {
            animation: spin 3s linear infinite;
          }
          .animate-spin-reverse-fast {
            animation: spin-reverse 1.5s linear infinite;
          }
        `}</style>

        {/* Data Sync Rings */}
        <div className="relative w-32 h-32 flex items-center justify-center">
          <div className="absolute w-full h-full border-4 border-t-transparent border-neon-cyan rounded-full animate-spin-slow opacity-80 shadow-[0_0_15px_rgba(0,240,255,0.5)]"></div>
          <div className="absolute w-3/4 h-3/4 border-4 border-b-transparent border-blue-400 rounded-full animate-spin-reverse-fast opacity-60"></div>
          <div className="absolute w-1/2 h-1/2 border-4 border-l-transparent border-white rounded-full animate-spin opacity-90"></div>
          <div className="font-mono text-neon-cyan font-bold tracking-widest animate-pulse">0101</div>
        </div>

        <h2 className="mt-8 text-sm font-bold tracking-[0.3em] font-orbitron uppercase text-neon-cyan animate-pulse drop-shadow-[0_0_8px_rgba(0,240,255,0.6)]">
          SYNCING CLUB DATA...
        </h2>
        <p className="text-[10px] uppercase font-mono tracking-widest text-gray-500 mt-3 opacity-60">
          Connecting to Telegram Secure Gateway...
        </p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="flex-1 flex flex-col items-center justify-center min-h-screen bg-space-dark p-6 text-center">
        <div className="w-16 h-16 mb-4 rounded-full bg-red-500/20 flex items-center justify-center border border-red-500/50 shadow-[0_0_20px_rgba(239,68,68,0.3)]">
          <span className="text-red-500 text-2xl font-black">!</span>
        </div>
        <h2 className="text-lg font-bold text-red-500 mb-2">Access Denied</h2>
        <p className="text-sm text-gray-400 mb-4">{error}</p>
        <button 
          onClick={() => window.location.reload()}
          className="px-6 py-2 bg-gray-900 border border-gray-700 rounded text-sm text-gray-300 hover:text-white hover:border-gray-500 transition-colors"
        >
          Retry
        </button>
      </div>
    );
  }

  return (
    <TelegramAuthContext.Provider value={{ isAuthenticated, userId, isLoading: false, error: null }}>
      {children}
    </TelegramAuthContext.Provider>
  );
}

import React from 'react';
import { Activity, Shield, Zap, Tag } from 'lucide-react';

interface Player {
  id: string;
  name: string;
  position: string;
  ovr: number;
  stamina: number;
  lineup_status?: string;
  is_nft_coach?: boolean;
  traits?: string[];
}

interface PlayerCardProps {
  player: Player;
  onSell?: () => void;
}

export function PlayerCard({ player, onSell }: PlayerCardProps) {
  const isStarter = player.lineup_status === 'starting';

  // Determine stamina color based on Match Engine consequences
  let staminaColor = 'bg-neon-green';
  if (player.stamina < 20) {
    staminaColor = 'bg-red-500 shadow-[0_0_10px_rgba(239,68,68,0.8)]'; // Critical
  } else if (player.stamina < 50) {
    staminaColor = 'bg-yellow-500 shadow-[0_0_10px_rgba(234,179,8,0.8)]'; // Warning
  } else {
    staminaColor = 'bg-neon-green shadow-[0_0_10px_rgba(57,255,20,0.5)]'; // Healthy
  }

  return (
    <div className={`relative bg-black/60 backdrop-blur-md border ${isStarter ? 'border-neon-cyan/50' : 'border-gray-800'} rounded-lg p-3 flex flex-col gap-3 shadow-[0_5px_15px_rgba(0,0,0,0.5)] overflow-hidden group hover:border-neon-cyan transition-colors`}>

      {/* Position Badge & OVR */}
      <div className="flex justify-between items-start">
        <div className="flex flex-col">
          <span className={`text-[10px] font-bold uppercase tracking-widest ${isStarter ? 'text-neon-cyan' : 'text-gray-500'}`}>
            {player.position}
          </span>
          <span className="text-sm font-bold text-white truncate max-w-[120px]" title={player.name}>
            {player.name}
          </span>
        </div>
        <div className="flex flex-col items-end">
          <div className="relative w-10 h-10 rounded-lg bg-gray-900 border border-gray-700 shadow-inner overflow-hidden flex items-center justify-center">
            <img 
              src={`https://api.dicebear.com/9.x/micah/svg?seed=${player.id}&backgroundColor=transparent`}
              alt="Avatar"
              className="w-full h-full object-cover mix-blend-screen opacity-90"
            />
            <div className="absolute bottom-0 right-0 bg-black/80 px-1 border-t border-l border-gray-700 rounded-tl">
              <span className="text-[9px] font-orbitron font-black text-white leading-none">{player.ovr}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Stamina Bar */}
      <div className="flex flex-col gap-1 mt-auto">
        <div className="flex justify-between items-center text-[10px] uppercase font-bold text-gray-400">
          <span className="flex items-center gap-1"><Activity size={10} /> Stamina</span>
          <span>{player.stamina}/100</span>
        </div>
        <div className="w-full h-1.5 bg-gray-900 rounded-full overflow-hidden border border-gray-800">
          <div 
            className={`h-full transition-all duration-500 ${staminaColor}`} 
            style={{ width: `${Math.max(0, Math.min(100, player.stamina))}%` }} 
          />
        </div>
      </div>

      {/* Decorators & Actions */}
      <div className="absolute top-0 right-0 flex items-start gap-1 p-1 z-10">
        {onSell && (
          <button 
            onClick={(e) => {
              e.stopPropagation();
              onSell();
            }}
            className="w-6 h-6 bg-red-900/60 hover:bg-red-600 border border-red-500/50 rounded flex items-center justify-center text-red-400 hover:text-white transition-colors"
            title="Sell Player"
          >
            <Tag size={12} />
          </button>
        )}
        {player.is_nft_coach && (
          <div className="w-6 h-6 bg-purple-900/60 border border-purple-500/50 rounded flex items-center justify-center text-purple-400">
            <Zap size={12} />
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { SquadManager } from './SquadManager';
import { getUpcomingOpponentScoutReport, ScoutReport } from '@/app/actions/scoutActions';
import { ShieldAlert, Crosshair, Lock } from 'lucide-react';

export function SquadTabs({ initialPlayers, teamId, userId }: { initialPlayers: any[], teamId: string, userId: string }) {
  const [activeTab, setActiveTab] = useState<'lineup' | 'scout'>('lineup');
  const [report, setReport] = useState<ScoutReport | null>(null);
  const [isLoadingScout, setIsLoadingScout] = useState(false);

  useEffect(() => {
    if (activeTab === 'scout' && !report) {
      setTimeout(() => setIsLoadingScout(true), 0);
      getUpcomingOpponentScoutReport(userId).then(res => {
        if (res.success && res.data) {
          setReport(res.data);
        }
        setIsLoadingScout(false);
      });
    }
  }, [activeTab, userId, report]);

  return (
    <div className="flex flex-col gap-4">
      {/* Tabs */}
      <div className="flex bg-black/40 border border-gray-800 p-1 rounded-lg">
        <button 
          onClick={() => setActiveTab('lineup')}
          className={`flex-1 py-2 text-xs font-bold uppercase tracking-widest rounded-md transition-all duration-300 ${activeTab === 'lineup' ? 'bg-neon-cyan text-black shadow-[0_0_15px_rgba(0,240,255,0.4)]' : 'text-gray-400 hover:text-white'}`}
        >
          Lineup
        </button>
        <button 
          onClick={() => setActiveTab('scout')}
          className={`flex-1 py-2 text-xs font-bold uppercase tracking-widest rounded-md transition-all duration-300 ${activeTab === 'scout' ? 'bg-red-600 text-white shadow-[0_0_15px_rgba(220,38,38,0.5)]' : 'text-gray-400 hover:text-white'}`}
        >
          Scout Intel
        </button>
      </div>

      {/* Content */}
      {activeTab === 'lineup' ? (
        <SquadManager initialPlayers={initialPlayers} teamId={teamId} />
      ) : (
        <div className="flex flex-col border border-gray-800 bg-black/60 rounded-xl overflow-hidden min-h-[300px] animate-in fade-in duration-300">
          {isLoadingScout ? (
            <div className="flex-1 flex justify-center items-center py-12">
               <div className="w-8 h-8 border-2 border-red-500 border-t-transparent rounded-full animate-spin"></div>
            </div>
          ) : !report || (report.players.length === 0 && report.fog_level !== 'hidden') ? (
