// ─────────────────────────────────────────────────────────────────────────────
// BottomTabBar — 6-tab navigation with progressive tutorial locking.
//
// Lock rules:
//   tutorial step 0  → all tabs locked except Home
//   tutorial step 1  → lineup unlocked (user must visit squad)
//   tutorial step 2+ → lineup + base unlocked
//   tutorial DONE    → all tabs unlocked
//
// Locked tabs show a 🔒 badge and show a toast on click.
// ─────────────────────────────────────────────────────────────────────────────

const LOCKED_TOAST_MSG = '🎓 Сначала пройди обучение!';

function isTabLocked(href: string, step: number): boolean {
  if (step === TUTORIAL_DONE) return false;
  if (href === '/' || href === '') return false;      // Home always open
  if (href === '/lineup' && step >= 1) return false;  // Unlocked at step 1
  if (href === '/base'   && step >= 2) return false;  // Unlocked at step 2
  return true; // everything else locked during tutorial
}

export function BottomTabBar() {
  const pathname = usePathname();
  const { language } = useContext(LanguageContext);
  const t = dict[language as keyof typeof dict];
  const { step, isDone } = useTutorial();

  const navItems = [
    { name: t.nav_home,   href: '/',        icon: Home,         id: 'tab-home'   },
    { name: t.nav_squad,  href: '/lineup',  icon: Users,        id: 'tab-lineup' },
    { name: 'База',       href: '/base',    icon: Building2,    id: 'tab-base'   },
    { name: 'Банк',       href: '/bank',    icon: Droplets,     id: 'tab-bank'   },
    { name: 'Рынок',      href: '/market',  icon: ShoppingCart, id: 'tab-market' },
    { name: t.nav_league, href: '/league',  icon: Trophy,       id: 'tab-league' },
  ];

  // Hide entirely on onboarding screen
  if (pathname === '/onboarding') return null;

  return (
    <div className="fixed bottom-0 w-full max-w-[480px] z-50
                    bg-gray-950/90 backdrop-blur-xl border-t border-white/5
                    shadow-[0_-4px_30px_rgba(0,0,0,0.5)] pb-safe">

      {/* Active tab glow line */}
      <div className="absolute top-0 left-0 right-0 h-px bg-gradient-to-r
                      from-transparent via-cyan-500/30 to-transparent" />

      <div className="flex overflow-x-auto scrollbar-none gap-0 px-1 py-2">
        {navItems.map((item) => {
          const isActive = pathname === item.href;
          const locked   = isTabLocked(item.href, step);
          const Icon     = item.icon;

          if (locked) {
            return (
              <button
                key={item.href}
                id={item.id}
                aria-label={`${item.name} (locked)`}
                className="flex-shrink-0 flex flex-col items-center justify-center
                           w-[16.666%] min-w-[56px] gap-0.5 relative
                           text-gray-700 active:text-gray-600 transition-colors duration-200"
                onClick={() =>
                  toast(LOCKED_TOAST_MSG, {
                    icon: '🔒',
                    duration: 2000,
                    style: { background: '#111', color: '#fff', border: '1px solid rgba(255,0,60,0.4)' },
                  })
                }
              >
                {/* Lock badge */}
                <div className="relative">
                  <Icon size={22} strokeWidth={1.5} className="opacity-30" />
                  <motion.span
                    className="absolute -top-1.5 -right-1.5 w-3.5 h-3.5 rounded-full
                               bg-red-500/80 flex items-center justify-center
                               shadow-[0_0_6px_rgba(239,68,68,0.6)]"
                    animate={{ scale: [1, 1.15, 1] }}
                    transition={{ repeat: Infinity, duration: 2, ease: 'easeInOut' }}
                  >
                    <Lock size={7} className="text-white" />
                  </motion.span>
                </div>
                <span className="text-[9px] uppercase font-bold tracking-wider opacity-30">
                  {item.name}
                </span>
              </button>
            );
          }

          return (
            <Link
              key={item.href}
              href={item.href}
              id={item.id}
              aria-label={item.name}
              className={`
                flex-shrink-0 flex flex-col items-center justify-center
                w-[16.666%] min-w-[56px] gap-0.5 transition-all duration-200
                active:scale-90
                ${isActive
                  ? 'text-cyan-400 drop-shadow-[0_0_8px_rgba(0,240,255,0.5)]'
                  : 'text-gray-500 hover:text-gray-300'
                }
              `}
            >
              <div className="relative">
                <Icon size={22} strokeWidth={isActive ? 2.5 : 1.8} />
                {isActive && (
                  <motion.span
                    className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-1 h-1
                               rounded-full bg-cyan-400 shadow-[0_0_6px_rgba(0,240,255,0.8)]"
                    layoutId="active-dot"
                    transition={{ type: 'spring', stiffness: 380, damping: 30 }}
                  />
                )}
              </div>
              <span className={`text-[9px] uppercase font-bold tracking-wider
                ${isActive ? 'text-cyan-400' : 'text-gray-500'}`}>
                {item.name}
              </span>
            </Link>
          );
        })}
      </div>
    </div>
  );
}

import crypto from 'crypto';

export interface TelegramUser {
  id: number;
  first_name: string;
  last_name?: string;
  username?: string;
  language_code?: string;
}

export interface ValidationResult {
  isValid: boolean;
  user?: TelegramUser;
  error?: string;
}

export function validateTelegramWebAppData(initData: string, botToken: string): ValidationResult {
  if (!initData) {
    return { isValid: false, error: 'Missing initData parameter' };
  }
  if (!botToken) {
    return { isValid: false, error: 'Missing bot token' };
  }

  try {
    const urlParams = new URLSearchParams(initData);
    const hash = urlParams.get('hash');

    if (!hash) {
      return { isValid: false, error: 'Invalid initData payload: missing hash' };
    }

    urlParams.delete('hash');

    const paramsArray: string[] = [];
    urlParams.forEach((value, key) => {
      paramsArray.push(`${key}=${value}`);
    });
    paramsArray.sort();

    const dataCheckString = paramsArray.join('\n');

    const secretKey = crypto.createHmac('sha256', 'WebAppData').update(botToken).digest();
    const calculatedHash = crypto.createHmac('sha256', secretKey).update(dataCheckString).digest('hex');

    if (calculatedHash !== hash) {
      return { isValid: false, error: 'Invalid cryptographic signature' };
    }

    const authDateStr = urlParams.get('auth_date');
    if (!authDateStr) {
      return { isValid: false, error: 'Missing auth_date' };
    }

    const authDate = parseInt(authDateStr, 10);
    const now = Math.floor(Date.now() / 1000);

    // Disallow initData older than 24 hours
    if (now - authDate > 86400) {
      return { isValid: false, error: 'Session expired' };
    }

    const userStr = urlParams.get('user');
    if (!userStr) {
      return { isValid: false, error: 'Missing user data payload' };
    }

    const user: TelegramUser = JSON.parse(userStr);

    return { isValid: true, user };

  } catch (error: any) {
    return { isValid: false, error: error.message };
  }
}

import { createClient } from '@supabase/supabase-js';
import * as dotenv from 'dotenv';
import { resolve } from 'path';

dotenv.config({ path: resolve(process.cwd(), '.env.local') });

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY;

if (!supabaseUrl || !supabaseKey) {
  console.error("Missing Supabase credentials in .env.local");
  process.exit(1);
}

const supabase = createClient(supabaseUrl, supabaseKey);

function getRandomInt(min: number, max: number) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

const firstNames = ['Liam', 'Noah', 'Oliver', 'Elijah', 'James', 'William', 'Benjamin', 'Lucas', 'Henry', 'Alexander', 'Mateo', 'Sebastian', 'Jack', 'Owen', 'Theodore'];
const lastNames = ['Smith', 'Johnson', 'Williams', 'Brown', 'Jones', 'Garcia', 'Miller', 'Davis', 'Rodriguez', 'Martinez', 'Hernandez', 'Lopez', 'Gonzalez', 'Wilson', 'Anderson'];

const AVAILABLE_TRAITS = ['Sniper', 'Playmaker', 'Wall', 'Speedster', 'Anchor', 'Poacher', 'Engine'];

function generatePlayer(teamId: string, position: string, status: string, isFreeAgent = false) {
  const stats = {
    pace: Math.max(30, getRandomInt(45, isFreeAgent ? 85 : 55)),
    shooting: Math.max(30, getRandomInt(45, isFreeAgent ? 85 : 55)),
    passing: Math.max(30, getRandomInt(45, isFreeAgent ? 85 : 55)),
    defending: Math.max(30, getRandomInt(45, isFreeAgent ? 85 : 55)),
    physical: Math.max(30, getRandomInt(45, isFreeAgent ? 85 : 55)),
  };

  const ovr = Math.floor((stats.pace + stats.shooting + stats.passing + stats.defending + stats.physical) / 5);
  const name = `${firstNames[getRandomInt(0, firstNames.length - 1)]} ${lastNames[getRandomInt(0, lastNames.length - 1)]}`;
  const traits = [AVAILABLE_TRAITS[getRandomInt(0, AVAILABLE_TRAITS.length - 1)]];

  return {
    team_id: teamId,
    name,
    age: getRandomInt(18, 25),
    ovr,
    potential_limit: getRandomInt(ovr + 5, 90),
    is_nft_coach: false,
    position,
    stats,
    stamina: 100,
    lineup_status: status,
    traits,
    is_for_sale: isFreeAgent
  };
}

async function generateSchedule(instanceId: string, teamIds: string[]) {
  const matchesToInsert = [];
  const numTeams = teamIds.length;
  const numRounds = numTeams - 1;
  const halfSize = numTeams / 2;
  const teams = [...teamIds];

  for (let round = 1; round <= numRounds; round++) {
    for (let i = 0; i < halfSize; i++) {
      const home = teams[i];
      const away = teams[numTeams - 1 - i];
      if (round % 2 === 0 && i === 0) {
        matchesToInsert.push({ league_instance_id: instanceId, round_number: round, home_team_id: away, away_team_id: home, is_played: false });
      } else {
        matchesToInsert.push({ league_instance_id: instanceId, round_number: round, home_team_id: home, away_team_id: away, is_played: false });
      }
    }
    const firstTeam = teams[0];
    const secondTeam = teams[1];
    teams.splice(1, 1);
    teams.push(secondTeam);
  }
  await supabase.from('league_matches').insert(matchesToInsert);
}

