  await supabase.from('users').delete().neq('id', '00000000-0000-0000-0000-000000000000');

  console.log("2. Creating System User for Market Seeding...");
  const { data: sysUser, error: sysUserErr } = await supabase.from('users').insert({
    telegram_id: 'sys_000',
